(window.TNQ=window.TNQ||[]).push({"terms":{"공기비":{"d":"실제 공급한 공기량을 이론공기량으로 나눈 값으로, 연소 조건을 판단하는 기준입니다.","r":["과잉공기량","등가비"]},"과잉공기량":{"d":"이론공기량보다 더 공급한 공기의 양으로, 완전연소를 돕지만 많으면 열손실이 커집니다.","r":["공기비"]},"등가비":{"d":"실제 연료 대 공기비를 이론 연료 대 공기비로 나눈 값으로, 1보다 크면 연료과잉입니다.","r":["공기비"]},"예혼합연소":{"d":"연료와 공기를 미리 섞어 공급해 태우는 방식으로, 불꽃이 짧고 화염온도가 높습니다.","r":[]},"역화":{"d":"혼합기체의 분출속도가 연소속도보다 느려 불꽃이 버너 안쪽으로 번지는 현상입니다.","r":["예혼합연소"]},"저위발열량":{"d":"고위발열량에서 수증기의 증발잠열을 뺀 발열량으로, 실제 이용 가능한 열량입니다.","r":["고위발열량"]},"고위발열량":{"d":"연소 때 생기는 수증기의 응축열까지 포함해 잰 발열량입니다.","r":["저위발열량"]},"초과부과금":{"d":"배출허용기준을 넘겨 오염물질을 배출한 사업자에게 초과 정도에 따라 매기는 부과금입니다.","r":[]},"분리계수":{"d":"원심력을 중력으로 나눈 값으로, 클수록 원심력집진장치의 먼지 분리 성능이 좋습니다.","r":[]},"복사역전":{"d":"맑고 바람이 약한 밤에 지표가 식으면서 지표 부근 공기가 위쪽보다 차가워지는 역전입니다.","r":["침강역전"]},"침강역전":{"d":"고기압에서 공기가 가라앉으며 단열압축되어 따뜻해져 생기는 역전으로 오래 지속됩니다.","r":["복사역전"]},"원추형":{"d":"중립 대기에서 굴뚝 연기가 원뿔 모양으로 퍼지는 연기 확산 형태입니다.","r":[]},"훈증형":{"d":"역전층이 사라지는 과정에서 연기가 지표 쪽으로 퍼져 지표 농도가 높아지는 확산 형태입니다.","r":["원추형"]},"광화학스모그":{"d":"질소산화물과 탄화수소가 햇빛을 받아 반응해 오존 등 산화제를 만드는 대기오염입니다.","r":["광화학산화제"]},"광화학산화제":{"d":"광화학반응으로 생기는 강한 산화성 물질로 오존, PAN, 과산화수소가 해당합니다.","r":["광화학스모그"]},"피토관":{"d":"전압과 정압의 차이로 동압을 재어 배출가스의 유속을 구하는 관입니다.","r":[]},"벤츄리스크러버":{"d":"가스가 좁은 목부를 빠르게 지나며 액체방울과 충돌해 입자를 씻어 내는 세정집진장치입니다.","r":["액가스비"]},"액가스비":{"d":"세정장치에서 처리가스 단위부피당 공급하는 세정액의 양입니다.","r":["벤츄리스크러버"]},"입자상물질":{"d":"물질이 파쇄, 선별, 연소, 합성 등으로 생겨 대기 중에 떠다니는 고체나 액체 입자입니다.","r":["매연"]},"매연":{"d":"연료가 연소할 때 생기는 유리탄소가 주성분인 미세한 입자상물질입니다.","r":["입자상물질"]},"런던스모그":{"d":"같은 SOx와 복사역전으로 겨울철 도시에 생긴 대기오염 사건입니다.","r":["복사역전"]},"비분산적외선분석법":{"d":"시료가스가 적외선을 흡수하는 양을 재어 CO 등의 농도를 분석하는 방법입니다.","r":[]},"당량비":{"d":"실제 연료 대 산화제 비를 이론 비로 나눈 값으로 등가비와 같은 뜻으로 씁니다.","r":["등가비"]},"탈진":{"d":"여과포 표면에 쌓인 먼지층을 털어 내어 여과 능력을 회복시키는 작업입니다.","r":[]},"활성탄":{"d":"표면적이 매우 넓은 탄소질 흡착제로 비극성 유기용제와 악취를 잘 흡착합니다.","r":[]},"탄화도":{"d":"석탄이 생성되는 과정에서 탄소 함량이 높아진 정도를 나타내는 지표입니다.","r":[]},"점결성":{"d":"석탄을 가열할 때 서로 달라붙어 덩어리가 되는 성질로 코크스 제조에서 따지는 성질입니다.","r":["코크스"]},"코크스":{"d":"원료탄을 건류해 얻는 2차 고체연료로 주성분은 탄소입니다.","r":["점결성"]},"흡광광도법":{"d":"시료 용액이 빛을 흡수하는 정도를 재어 성분의 농도를 구하는 분석법입니다.","r":["흡광도"]},"흡광도":{"d":"입사광에 대한 투과광의 비를 나타내는 투과도에 로그를 취하고 부호를 바꾼 값입니다.","r":["흡광광도법"]},"분산모델":{"d":"배출원에서 나온 오염물질이 퍼지는 과정을 계산해 농도를 예측하는 대기질 모델입니다.","r":[]},"제어속도":{"d":"오염물질 발생속도를 이기고 후드로 빨아들이는 데 필요한 최소 기류속도입니다.","r":[]},"물리흡착":{"d":"분자 사이의 약한 인력으로 흡착되어 온도가 오르면 흡착량이 줄어드는 흡착입니다.","r":[]},"비저항":{"d":"전기집진에서 먼지층의 전기가 통하기 어려운 정도로, 집진 성능을 좌우합니다.","r":["역전리"]},"역전리":{"d":"먼지층의 비저항이 너무 높아 집진극에서 반대 극성 이온이 방출되는 현상입니다.","r":["비저항"]},"전향력":{"d":"지구 자전 때문에 운동하는 물체의 방향을 바꾸는 겉보기 힘으로 코리올리 힘이라고도 합니다.","r":[]},"온위":{"d":"공기를 건조단열적으로 기준 기압면까지 옮겼을 때 갖는 온도입니다.","r":[]},"라돈":{"d":"무색무취의 방사성 기체로 공기보다 무겁고 폐암의 원인이 됩니다.","r":[]},"다이옥신":{"d":"불완전연소 때 생기는 염소화합물로, 독성이 강하고 토양에 쉽게 흡수되는 지용성 물질입니다.","r":[]},"충전탑":{"d":"탑 안에 충전물을 채우고 액체와 가스를 접촉시켜 가스를 흡수하는 장치입니다.","r":["분무탑"]},"분무탑":{"d":"충전제 없이 액체를 분무해 가스와 접촉시키는 구조가 간단한 흡수장치입니다.","r":["충전탑"]},"가우시안모델":{"d":"연기 농도가 정규분포 모양으로 퍼진다고 가정하는 대기확산 모델입니다.","r":[]},"해풍":{"d":"바다와 육지의 비열 차이로 낮에 바다에서 육지로 부는 바람입니다.","r":[]},"폭굉유도거리":{"d":"가연성 가스가 관 안에서 연소를 시작해 폭굉으로 바뀔 때까지 걸리는 거리입니다.","r":[]},"관성충돌법":{"d":"입자의 관성을 이용해 입경별로 분리 포집하여 입경분포를 재는 방법입니다.","r":[]},"열섬효과":{"d":"도시 중심부의 기온이 인공열과 지표 특성 때문에 교외보다 높아지는 현상입니다.","r":[]},"레일리산란":{"d":"입자가 빛의 파장보다 훨씬 작을 때 일어나는 산란으로, 산란 세기는 파장의 4제곱에 반비례합니다.","r":[]},"산성비":{"d":"산성 물질이 녹아 pH가 보통 빗물보다 낮아진 비입니다.","r":[]},"자가측정":{"d":"배출시설을 운영하는 사업자가 스스로 오염물질을 측정하고 기록하는 일입니다.","r":[]},"비산먼지":{"d":"일정한 배출구 없이 공사장이나 야적장 등에서 대기로 날리는 먼지입니다.","r":[]}},"notes":{"(CO2)max는 연료 조성마다 정해지는 고유값이다":"(CO2)max는 연료를 이론공기량으로 완전연소할 때 나오는 최대 탄산가스 농도이고, 연료마다 값이 정해져 있어요.","0.3㎛ 입자를 99% 이상 포집할 수 있어야 한다":"여과지는 지름 0.3㎛ 입자를 99% 넘게 걸러 낼 만큼 촘촘해야 합니다.","0.5mmH2O가 아니라 0.3mmH2O 눈금을 읽을 수 있어야 한다":"압력차를 읽는 눈금은 0.3mmH2O 단위까지 필요하고 0.5mmH2O 단위는 맞지 않습니다.","1.2~1.5m나 3~5m가 아니라 1.5~10m 범위로 한다":"채취 높이는 1.2~1.5m나 3~5m가 아닌 1.5~10m 범위입니다.","100~2000ppm 범위이며 산화·환원성가스에 방해받는다":"황화수소 요오드 적정법은 100~2000ppm 범위에 쓰고 산화·환원성가스의 방해를 받아요.","100분의 20이나 제품명 위에 표시하는 것은 기준에 맞지 않는다":"100분의 20 크기이거나 제품명 위에 적는 표시는 기준에 맞지 않습니다.","10^12 이상에서 역전리가 생긴다":"비저항이 10^12 이상으로 높으면 역전리 현상이 나타납니다.","10^4 이하에서 재비산이 생긴다":"비저항이 너무 낮으면 쌓인 먼지가 쉽게 떨어져 다시 날아오릅니다.","160km 이상이 제5종이거나, 80~160km가 1종·3종인 것은 아니다":"160km 이상이 제5종이라거나 80~160km가 1종이나 3종이라는 설명은 틀립니다.","180~2850nm 파장의 제논램프를 광원으로 쓴다":"DOAS는 180~2850nm 파장을 내는 제논램프를 광원으로 사용해요.","1개월당 금액×업무정지월수이며 5천만원을 초과할 수 없다":"과징금은 1개월당 금액에 업무정지월수를 곱해 구하며 5천만원을 넘을 수 없습니다.","1년 이하 징역 또는 1천만원 이하 벌금이다":"공기질 유지기준을 위반하면 1년 이하 징역 또는 1천만원 이하 벌금입니다.","1보다 크면 공기부족(농후)한 상태를 뜻한다":"등가비가 1보다 크면 연료가 많고 공기가 부족한 농후 상태예요.","1회 24시간 이상 연속 채취하며 풍속 0.5m/s 미만이면 채취하지 않는다":"비산먼지는 1회 24시간 이상 연속으로 채취하고, 풍속이 0.5m/s 미만이면 채취하지 않아요.","2.54mmHg 이내에서 대기압을 측정할 수 있어야 한다":"기압계는 2.54mmHg 이내의 오차로 대기압을 잴 수 있어야 해요.","20~30m/s가 아니라 60~90m/s 수준이다":"벤츄리스크러버 목부의 가스속도는 20~30m/s가 아니라 60~90m/s 수준입니다.","20톤 이상 80톤 미만 시설은 월 1회가 아니라 다른 주기로 측정한다":"20톤 이상 80톤 미만 시설은 월 1회가 아닌 별도 측정주기가 정해져 있습니다.","213.8nm에서 불꽃 흡수로 바탕선 보정이 필요하다":"아연은 213.8nm에서 불꽃 자체가 빛을 흡수하므로 바탕선 보정을 해야 해요.","2~10L 백을 사용해 1~2L/min으로 흡인한다":"테들라백법은 2~10L 백을 사용하고 1~2L/min으로 흡인합니다.","2단연소, 배기가스재순환, 공기예열온도 낮추기로 NOx를 저감한다":"연소를 두 번에 나누고 배기가스를 되돌리고 공기 예열을 낮추면 질소산화물이 줄어듭니다.","2단연소, 저온연소, 배기가스재순환으로 NOx 발생을 줄인다":"2단연소, 저온연소, 배기가스재순환 모두 열적 NOx가 생기는 것을 줄여 줍니다.","2차오염물질의 반응·응축 생성물이 직접 원인인 것은 아니다":"2차오염물질의 반응과 응축 생성물이 직접 원인이라는 설명은 맞지 않습니다.","2차오염원 확인이 가능하고 점·선·면 오염원 영향을 평가한다":"분산모델은 2차오염원을 확인할 수 있고 점, 선, 면 오염원의 영향을 평가해요.","3000K 고온 연소에서 CO가 많이 생기는 이유는 이산화탄소의 열분해 때문이다":"3000K 정도의 고온 연소에서 CO가 많은 까닭은 이산화탄소가 열분해되기 때문이에요.","313nm 이하에서 광분해하며 오존·PAN·과산화수소가 광화학산화제다":"알데하이드는 313nm 이하 빛에 분해되며, 오존, PAN, 과산화수소가 광화학산화제입니다.","32.0~38%·비중1.38이 아니라 다른 수치":"암모니아수는 32.0~38%, 비중 1.38이 아니라 다른 수치예요.","420nm 이상 빛에 광분해돼 NO+O→O3를 만드는 핵심 흡수기체다":"이산화질소가 빛을 받아 일산화질소와 산소원자로 쪼개지며, 그 산소원자가 오존을 만듭니다.","46.0~48.0%·비중1.14":"플루오르화수소산은 농도 46.0~48.0%, 비중 1.14인 시약입니다.","47.0~49.0%·비중1.48":"브롬화수소산은 농도 47.0~49.0%, 비중 1.48인 시약이에요.","490nm에서 측정하며 추출제로 디티존사염화탄소를 쓴다":"디티존사염화탄소로 뽑아 490nm에서 색의 진하기를 잽니다.","4πR²/πR²이나 πR/2πR² 형태로 계산하는 것은 아니다":"평균 일사량은 4πR²/πR²이나 πR/2πR²로 구하지 않습니다.","4명 이상이며 자동차·화공·환경 분야 자격자를 포함해야 한다":"자동차연료 검사기관의 검사원은 4명 이상이며 자동차, 화공, 환경 분야 자격자를 포함해야 합니다.","50㎛ 이상 입자에 적합하며 온도변화 영향을 거의 받지 않는다":"중력식집진장치는 50㎛ 이상 입자에 알맞고 온도변화의 영향을 거의 받지 않습니다.","5종 사업장 관리인을 둘 수 있다":"일반 보일러만 설치한 사업장에는 5종 사업장 관리인을 환경기술인으로 둘 수 있어요.","60.0~62.0%·비중1.54":"과염소산은 농도 60.0~62.0%, 비중 1.54인 시약입니다.","80% 교정가스를 스팬가스라 하지 않으며, 반응시간은 최종값 50% 도달시간이 아니다":"교정가스의 80%짜리를 스팬가스로 부르지 않으며, 반응시간도 50% 도달 기준이 아닙니다.","80% 집진장치 2개를 직렬연결한 총효율은 94%가 아니라 96%다":"집진효율 80%인 장치 2개를 직렬로 이으면 총효율은 94%가 아니라 96%입니다.","90% 유출온도는 170℃ 이하, 벤젠함량은 0.7부피% 이하다":"자동차연료는 90% 유출온도가 170℃ 이하, 벤젠함량이 0.7부피% 이하여야 합니다.","API도는 비중에 반비례하며, 비중이 커져도 착화점이 높아지지 않는다":"API도는 비중이 커지면 작아지는 반비례 관계이고, 착화점은 비중과 이런 식으로 움직이지 않습니다.","C/H비는 15~20이며 액체연료보다 수소함유량은 적고 산소함유량은 크다":"고체연료는 C/H비가 15~20이고 액체연료보다 수소는 적고 산소는 많이 들어 있습니다.","C/H비·점도·잔류탄소가 늘어난다":"비중이 큰 석유에서는 C/H비, 점도, 잔류탄소가 늘어납니다.","CFC-11·12는 CHFCl2나 CF3Br, CH2FCl이 아니다":"CFC-11과 CFC-12의 화학식은 CHFCl2, CF3Br, CH2FCl과 다릅니다.","CH4·H2가 주성분이고 발열량이 고로가스보다 크다":"코크스가스는 CH4와 H2가 주성분이고 발열량이 고로가스보다 큽니다.","CH4·N2O 주요 흡수대는 파장 7~8㎛대이며 교토의정서는 온실가스 감축 국제협약이다":"7~8㎛ 파장대에서 CH4와 N2O가 빛을 흡수하고, 교토의정서는 온실가스를 줄이기 위한 협약입니다.","CO2는 식물보다 해수에 흡수되는 양이 많다":"CO2를 빨아들이는 몫은 식물보다 바닷물 쪽이 더 큽니다.","CO2이며 10% 이상이면 위험하다":"실내공기오염의 지표물질은 CO2이고, 농도가 10% 이상이면 위험해요.","CO·HC·NOx를 동시에 80% 이상 저감할 수 있다":"삼원촉매장치는 CO, HC, NOx를 동시에 80% 이상 줄일 수 있습니다.","CO는 수용성이어서 강우 영향이 크거나 체류시간이 1~3년인 것이 아니다":"CO는 수용성이라 강우 영향이 크다거나 체류시간이 1~3년이라는 설명은 틀립니다.","Ca-EDTA, 페니실아민, DMSA 등을 쓴다":"납에 중독되면 Ca-EDTA, 페니실아민, DMSA 같은 약을 해독제로 씁니다.","Cmax는 오염물질 배출량에 비례한다":"Sutton식에서 Cmax는 오염물질 배출량에 비례합니다.","Cmax는 오염물질 배출율에 비례한다":"최대착지농도 Cmax는 오염물질 배출율에 비례합니다.","Cmax는 유효굴뚝높이(He)의 제곱에 반비례해 He가 2배면 Cmax는 1/4로 준다":"Cmax는 He의 제곱에 반비례하므로, He가 2배면 Cmax는 4분의 1이 됩니다.","Cmax는 유효굴뚝높이의 제곱에 반비례하며 수평·수직 확산계수와 관계가 있다":"Cmax는 유효굴뚝높이 제곱에 반비례하며 확산계수와도 이어져 있습니다.","Cmax는 평균풍속에 비례하는 것이 아니라 반비례한다":"평균풍속과 Cmax는 서로 반비례하는 관계입니다.","Cu는 324.75nm, Cd는 226.50nm, Pb는 220.35nm다":"ICP법에서 측정파장은 Cu 324.75nm, Cd 226.50nm, Pb 220.35nm입니다.","ECD는 탄화수소·알코올·케톤에 감도가 우수한 것이 아니다":"탄화수소, 알코올, 케톤은 ECD가 민감하게 잡는 성분이 아닙니다.","EGR제어용 서모밸브는 자기진단장치가 아니며, 재생용가열기·PVC밸브는 증발가스방지장치가 아니다":"자기진단장치와 증발가스 방지장치에는 서로 다른 부품이 속하며, 이 부품들은 해당하지 않습니다.","FID(수소염이온화검출기)를 이용한 GC법으로 측정한다":"수소염이온화검출기(FID)를 단 GC로 총탄화수소를 잽니다.","FPD(불꽃광도검출기)로 분석한다":"이황화탄소를 가스크로마토그래프법으로 분석할 때는 FPD(불꽃광도검출기)를 씁니다.","GC/MS로 분석하며 대체표준물질(surrogate) 등 용어를 쓴다":"기체크로마토그래프에 질량분석기를 붙여 재며, 분석 때 대체표준물질을 넣어 회수율을 봅니다.","GC 정량분석법에 해당하지 않는다":"표준첨가법은 GC 정량분석법에 해당하지 않습니다.","HF는 Ca(OH)2로 CaF2를 만들며, Cl2가 Ca(ClO3)2로 되는 것은 아니다":"HF는 Ca(OH)2와 만나 CaF2가 되고, Cl2가 Ca(ClO3)2가 된다는 설명은 틀립니다.","HL=Gw×Cpm×(Tbt-To)로 계산한다":"열손실 HL은 가스 질량과 평균비열에 연소 온도와 기준 온도의 차를 곱해 구합니다.","MMD는 밤에 가장 크거나 낮에 20~30m로 작아지는 것이 아니다":"MMD는 밤에 가장 크지 않고, 낮에도 20~30m 같은 낮은 값으로 줄지 않습니다.","N/10-NaOH 역가는 술파민산용액으로 표정하며 지시약 변색점은 pH 5.4다":"N/10-NaOH의 정확한 농도는 술파민산용액으로 맞추고, 지시약은 pH 5.4에서 색이 변합니다.","NH3를 환원제로 써 NOx를 질소분자와 물로 선택적 환원한다":"SCR은 NH3를 환원제로 써서 NOx를 질소분자와 물로 선택적으로 환원하는 방식이에요.","NO2는 NO보다 수용성이 낮으며, '웃음기체'가 아니다":"NO2는 NO보다 물에 덜 녹지 않고, 웃음기체는 N2O를 가리킵니다.","NOCl·C3H8은 각각 1차·2차 오염물질 구분에서 제외된다":"NOCl과 C3H8은 1차와 2차를 가르는 구분에서 빠집니다.","NOx와 헤모글로빈의 친화력은 CO보다 강하지 않다":"NOx와 헤모글로빈의 친화력은 CO와 헤모글로빈의 친화력보다 강하지 않아요.","NOx·탄화수소의 광화학반응으로 생성돼 엽록소 파괴를 일으킨다":"오존은 NOx와 탄화수소의 광화학반응으로 생기고 식물의 엽록소를 파괴합니다.","O3 주요 흡수대는 13~17㎛가 아니며, CO2 농도는 여름에 증가하는 것이 아니라 감소한다":"O3의 주요 흡수대는 13~17㎛가 아니며, CO2 농도는 여름에 늘지 않고 줄어듭니다.","PAH는 물에 쉽게 녹는 것이 아니라 소수성이어서 강우 영향이 적다":"PAH는 물에 쉽게 녹지 않는 소수성이라 강우의 영향이 적습니다.","PAN(CH3C(O)O2NO2)은 강산화제로 눈 자극과 가시거리 감소를 일으킨다":"PAN(CH3C(O)O2NO2)은 산화력이 강해 눈을 따갑게 하고 시야를 흐리게 합니다.","PCB 부분산화·불완전연소로 생성되며 2,3,7,8-TCDD가 가장 유해하다":"PCB가 일부만 산화되거나 덜 탈 때 생기고, 2,3,7,8-TCDD가 독성이 가장 큽니다.","PM10 200, CO2 1000ppm, CO 10ppm 이하다":"대규모점포 유지기준은 PM10 200, CO2 1000ppm, CO 10ppm 이하로 정해져 있어요.","R(%)=100exp(-β·dp^n) 식에서 β는 입경계수, n은 입경지수다":"R(%)=100exp(-β·dp^n)에서 β는 입경 크기를, n은 분포 폭을 정하는 상수입니다.","Ri는 기계적 난류 대 대류난류(열적난류)의 비를 나타내는 무차원수다":"Ri는 두 가지 난류의 비율을 숫자 하나로 나타낸 단위 없는 수입니다.","Ri는 기계적 난류를 대류난류로 전환시키는 율이 아니라 그 반대 비를 뜻한다":"Ri는 기계적 난류가 대류난류로 바뀌는 율이 아니라, 반대로 대류난류에 대한 기계적 난류의 비를 뜻해요.","SO2·CO·NO2·오존·먼지·벤젠·납이며 탄화수소는 제외다":"대기환경기준 항목은 SO2, CO, NO2, 오존, 먼지, 벤젠, 납이고 탄화수소는 들어가지 않아요.","SO2를 함유한 공기는 부식성이 강해지며 분진과 반응해 황산염을 만들어 금속을 부식시킨다":"SO2가 든 공기는 분진과 만나 황산염이 되어 금속을 녹슬게 합니다.","Sv=3ρ/D나 2/d, 4/d로 나타내는 것은 아니다":"3ρ/D, 2/d, 4/d는 구형입자의 비표면적을 나타내는 올바른 식이 아닙니다.","Thermal·Fuel·Prompt NOx 3가지로 분류되며 화염온도가 높을수록 생성이 커진다":"NOx는 Thermal, Fuel, Prompt NOx 3가지로 나뉘며 화염온도가 높을수록 생성이 많아요.","V2O5·TiO2, Pt·Pd 등을 촉매로 쓴다":"촉매분해에는 V2O5·TiO2와 Pt·Pd 같은 촉매가 쓰입니다.","VOCs 종류에 따라 흡착·흡수·연소 등 적합한 제어기술이 다르다":"VOCs 종류가 다르면 맞는 제어기술도 흡착, 흡수, 연소 중에서 달라집니다.","Zn은 213.8nm를 쓴다":"원자흡광광도법으로 아연을 재려면 213.8nm 파장을 씁니다.","Zn의 ICP 측정파장은 259.94nm가 아니며, Pb·Cu의 AAS 파장도 다른 수치가 아니다":"Zn 파장은 ICP와 AAS에서 서로 다르며, 문장이 말한 수치는 맞지 않습니다.","m=A/Ao=21/(21-O2)=1+(과잉공기량/Ao)로 구한다":"공기비 m은 실제공기량을 이론공기량으로 나눈 값이며, 배기가스의 산소 농도로도 구할 수 있습니다.","methyl 측쇄가 많고 중앙에 집중할수록 옥탄가가 높아진다":"iso-파라핀은 methyl 측쇄가 많고 중앙에 모일수록 옥탄가가 높아집니다.","n-발레르알데하이드 0.02ppm, 톨루엔 30ppm 이하다":"n-발레르알데하이드는 매우 낮은 농도로, 톨루엔은 그보다 높은 농도로 배출을 제한합니다.","pH 10이 아니라 pH 1에서 메틸수소화비소를 생성한다":"메틸비소화합물은 pH 10이 아니라 pH 1에서 메틸수소화비소를 만들어요.","poise, Pa·s, g/(cm·s)이며 liter·atm은 아니다":"점도는 poise, Pa·s, g/(cm·s) 단위를 쓰고 liter·atm은 에너지 단위입니다.","van der Waals 힘으로 결합하며 온도가 오르면 흡착량이 준다":"van der Waals 힘으로 붙는 흡착이라서 온도가 높아지면 붙어 있던 양이 줄어듭니다.","β가 클수록 입경이 미세하고, n이 클수록 입경분포범위가 좁다":"β가 크면 작은 입자가 많고, n이 크면 입자 크기가 한곳에 모입니다.","β가 클수록 입경이 크거나 n이 클수록 분포범위가 넓은 것은 아니다":"β가 클수록 입자가 크다거나 n이 클수록 분포가 넓다는 설명은 반대입니다.","Ⅰ(주거)1.5, Ⅱ(공업)0.5, Ⅲ(녹지)1.0이다":"지역별 부과계수는 Ⅰ(주거)가 1.5, Ⅱ(공업)가 0.5, Ⅲ(녹지)가 1.0이에요.","가늘고 뾰족할수록 코로나 방전이 쉽고 진동·요동이 없어야 한다":"가늘고 끝이 뾰족하면 코로나 방전이 잘 일어나고, 흔들리지 않게 고정해야 합니다.","가능한 수직으로 연결하고 응축수가 배수되도록 한다":"도관은 가능한 한 수직으로 연결하고 응축수가 빠지도록 합니다.","가동개시 신고 없이 조업하거나 배출시설을 방치한 것은 1차 조업정지 대상이 아니다":"가동개시 신고 없이 조업하거나 시설을 방치한 경우는 1차 조업정지가 아닌 다른 처분을 받습니다.","가볍고 기계적 강도·내식성이 크며 단위부피당 표면적이 커야 한다":"충전물은 가볍고 기계적 강도와 내식성이 크며 단위부피당 표면적이 넓어야 합니다.","가볍고 내식성이 있어야 하며 입자가 받는 쿨롱힘은 ne0E다":"가벼우면서 부식에 강해야 하고, 입자가 받는 쿨롱힘은 ne0E로 나타냅니다.","가솔린기관보다 자기착화온도가 높고 검댕·CO·HC 배출이 많다":"디젤은 가솔린기관보다 자기착화온도가 높고 검댕, CO, HC 배출이 많다는 말은 맞지 않습니다.","가스압이 높아지면 폭발하한은 거의 안 변하고 상한값이 높아진다":"압력이 높아져도 하한은 거의 그대로이고 상한만 올라갑니다.","가스 온도가 높아지면 폭발범위는 넓어진다":"온도가 오르면 가스가 터질 수 있는 농도 범위가 더 넓어집니다.","가스와 흡착제의 접촉시간이 긴 것이 요구된다":"가스와 흡착제가 닿는 시간이 긴 것이 흡착장치의 구비조건입니다.","가스크로마토그래프법(FID)":"환경기준 항목 중 일산화탄소는 가스크로마토그래프법(FID)으로 분석합니다.","가시거리를 증가시키는 것이 아니라 감소시키며, 분자식도 C6H5COOONO2가 아니다":"PAN은 시야를 넓히는 물질이 아니고, 화학식도 C6H5COOONO2와 다릅니다.","가시부 광원은 텅스텐램프, 자외부 광원은 중수소방전관을 쓴다":"흡광광도법의 광원은 가시부에서 텅스텐램프, 자외부에서 중수소방전관을 씁니다.","가시부는 유리제, 자외부는 석영제를 쓴다":"흡수셀은 가시부에서는 유리제, 자외부에서는 석영제를 사용해요.","가장 빈번한 풍향으로 막대 길이를 가장 길게 표시한다":"바람장미에서는 가장 자주 부는 풍향의 막대를 가장 길게 그립니다.","감마알루미나 담체 표면에 나트륨(탄산나트륨)을 입혀 SOx·NOx를 동시 제거한다":"나트륨을 입힌 감마알루미나 표면에서 SOx와 NOx를 함께 떼어 내는 공정입니다.","값이 싸지만 흡수성이 높고 내산성이 약하다":"목면은 값이 싸지만 흡수성이 높고 내산성이 약해요.","강우 산성화에 가장 큰 영향을 주는 것은 아황산가스이며, 국제협약으로 헬싱키·소피아 의정서가 있다":"아황산가스가 비를 가장 산성으로 만들며, 헬싱키·소피아 의정서가 이를 다룹니다.","개선명령 불이행, 방지시설 미설치 가동, 방지시설 임의철거":"개선명령을 안 따르거나 방지시설을 설치하지 않고 돌리거나 멋대로 철거하면 해당합니다.","개선명령을 받으면 정해진 기간 내 계획서를 제출해야 한다":"개선명령을 받은 사업자는 정해진 기간 안에 개선계획서를 제출해야 합니다.","개선명세서·설계도, 처리방식·효율, 공사기간·공사비":"개선계획서에는 개선명세서와 설계도, 처리방식과 효율, 공사기간과 공사비를 담아요.","건식보다 가스처리속도를 2배 정도 크게 할 수 있다":"습식 전기집진장치는 건식보다 가스처리속도를 2배 정도 크게 할 수 있습니다.","건조단열감률이 환경감률보다 작을 때가 아니라 그 사이인 조건이다":"미단열조건은 건조단열감률이 환경감률보다 작을 때가 아니라 그 사이일 때입니다.","건조배출가스 유량은 표준상태 기준 Sm3(5분적산치)로 나타낸다":"건조한 배출가스의 유량은 표준상태로 환산한 Sm3로, 5분 동안 쌓은 값으로 적습니다.","검사원은 2명 이상이 아니라 4명 이상이 기준이다":"검사원 수 기준은 2명이 아니라 4명입니다.","검출기로 수소염이온화검출기(FID)를 쓰는 것은 아니다":"이온크로마토그래피의 검출기로 수소염이온화검출기(FID)를 쓰지는 않아요.","경자동차 배기량은 800cc 미만이며 건설기계는 19~560KW 출력이다":"800cc 미만이 경자동차 배기량이고, 건설기계는 출력 19~560KW 범위입니다.","경질유리·석영·불소수지를 쓴다":"포름알데히드의 채취관과 도관에는 경질유리, 석영, 불소수지를 씁니다.","고기압에서 기층이 단열압축되며 승온돼 생기고 장시간 지속된다":"침강역전은 고기압에서 공기층이 단열압축되어 따뜻해지면서 생기고 오래 이어집니다.","고농도는 직렬, 응집성 강한 먼지는 병렬연결이 유리한 것은 아니다(그 반대)":"고농도는 직렬, 응집성이 강한 먼지는 병렬연결이 유리하다는 설명은 반대로 쓴 말입니다.","고농도 함진가스나 높은 집진율을 위해 간헐적으로 떠는 방식이 유리한 것은 아니다":"고농도 가스이거나 집진율을 높이려는 경우라면 간헐식 털기가 늘 유리하지는 않습니다.","고도에 따라 온도가 상승한다":"대류권과 성층권은 고도가 올라갈 때 온도가 상승한다는 말은 틀립니다.","고발열량 가스를 노즐에서 고속분출시켜 쓴다":"방사형 버너는 발열량이 높은 가스를 노즐에서 빠르게 내뿜어 사용해요.","고온 CO 발생은 혼합불량이나 산소부족이 아니라 CO2 열분해가 주원인이다":"고온에서 CO가 생기는 주원인은 혼합불량이나 산소부족이 아니라 CO2의 열분해입니다.","고온 완전분해 후에도 저온에서 재생성될 수 있으며, 유해폐기물 소각이 수천배 더 배출하는 것은 아니다":"다이옥신은 고온에서 완전히 분해한 뒤에도 저온에서 다시 생길 수 있고, 유해폐기물 소각이 수천 배 더 배출하는 것은 아닙니다.","고위발열량에서 수분·생성수증기의 증발잠열을 뺀 값이다":"저위발열량은 고위발열량에서 수분과 생성 수증기의 증발잠열을 뺀 값이에요.","고저항 먼지로 인한 역전리 현상은 습식에서 잘 일어나지 않는다":"고저항 먼지 때문에 생기는 역전리 현상은 습식에서는 잘 일어나지 않아요.","고체연료 분자량이 250 전후인 것은 아니며, 코크스는 매연이 적게 난다":"고체연료의 분자량이 250 전후라는 말은 틀리며, 코크스는 매연이 적게 납니다.","곡률반경이 작을수록 미세먼지를 잘 분리하며 압력손실은 30~70mmH2O다":"휘어지는 반지름이 작을수록 미세한 먼지를 더 잘 떼어 내며 압력손실은 30~70mmH2O입니다.","공급 공기량이 적으면 탄소입자가 생겨 화염이 황색을 띤다":"공기가 모자라면 타지 못한 탄소 입자가 생겨 불꽃이 노랗게 보입니다.","공기를 건조단열적으로 기준기압면(보통 1000mb)까지 옮긴 온도다":"공기를 열 출입 없이 기준 기압면(보통 1000mb)까지 옮겼을 때의 온도가 온위입니다.","공기만 압축해 압축비가 높아 연비가 좋다":"디젤기관은 공기만 압축하고 압축비가 높아서 연비가 좋아요.","공기부족·불완전연소가 생기는 것이 아니라 공기과잉(희박) 상태다":"이 경우는 연료에 비해 공기가 남아도는 희박 상태이며, 공기가 모자란 상태가 아닙니다.","공기부하시험시, 방전극이 너무 가늘 때 2차전류가 많이 흐른다":"공기만 통과시키는 시험을 할 때나 방전극이 지나치게 가늘 때 2차전류가 세집니다.","공기비가 커도 SOx가 줄거나 폭발위험이 커지는 것은 아니다":"공기가 많아져도 SOx가 줄거나 폭발 위험이 커지지는 않습니다.","공기와 연료의 질량비(또는 부피비)로 예혼합연소에서 주로 쓴다":"공연비는 공기와 연료의 질량비 또는 부피비이고 예혼합연소에서 주로 씁니다.","공기 접촉면이 많아 거의 완전연소하며 부하변동에 잘 대응한다":"미분탄 연소는 공기와 닿는 면이 많아 거의 완전연소하고 부하변동에 잘 대응해요.","공동방지시설 위치도(축척 2만5천분의1 지형도)를 제출한다":"공동방지시설이 어디에 있는지 축척 2만5천분의1 지형도에 표시해 냅니다.","공동임명된 환경기술인이 사업장에 번갈아 근무하면 안 되는 것은 아니다":"함께 임명된 환경기술인이 사업장마다 교대로 일하는 것은 금지되어 있지 않습니다.","공정 온도가 850~1000℃인 것은 아니며, CuSO2 형태로 이동되는 것도 아니다":"공정 온도가 850~1000℃라거나 CuSO2로 옮겨 간다는 설명은 틀립니다.","공차중량 1.0톤 이상 이륜차가 경자동차로 분류되거나, 이륜차 중량이 0.5톤 미만 기준은 아니다":"무게가 1.0톤 이상인 이륜차를 경자동차로 보거나 0.5톤 미만을 이륜차 기준으로 삼지 않습니다.","과불화탄소·수소불화탄소·아산화질소·메탄":"기후·생태계변화 유발물질에는 과불화탄소, 수소불화탄소, 아산화질소, 메탄이 있어요.","과산화수소수에 흡수시켜 황산으로 만든다":"황산화물은 과산화수소수에 흡수시켜 황산으로 바꾼 뒤 분석합니다.","과잉공기량을 많게 하는 것은 NOx 저감법이 아니라 오히려 늘리는 요인이다":"공기를 많이 넣는 것은 NOx를 줄이는 방법이 못 되고 오히려 늘리는 원인입니다.","과잉공기로 충분히 연소시킨 배출량이 아니라 이론값이다":"이론공기량만 쓴 가상의 값이므로, 실제 배출가스의 측정값과는 다릅니다.","과잉공기를 적게 해도 완전연소가 가능하나 비산재가 많아 집진장치가 필요하다":"미분탄은 과잉공기를 적게 써도 완전연소하지만 비산재가 많아 집진장치가 필요합니다.","관내경이 굵거나 방해물이 없으면 폭굉유도거리는 길어진다":"관이 굵고 방해물이 없으면 연소파가 가속되기 어려워 폭굉까지 거리가 늘어납니다.","관 내경이 클수록, 직경이 클수록 압력손실은 작아진다":"관 지름이 넓으면 가스가 흐르기 편해 압력손실이 줄어듭니다.","광산란법·관성충돌법은 직접측정법이 아니라 간접측정법이다":"광산란법과 관성충돌법은 입경을 직접 보는 방법이 아니라 간접으로 구하는 방법입니다.","광원부-파장선택부-시료부-측광부로 구성된다":"흡광분석장치는 광원부, 파장선택부, 시료부, 측광부로 이루어집니다.","광원은 니크롬선·탄화규소 저항체를 가열해 쓰고 시료셀은 시료광속이 통과한다":"광원은 니크롬선이나 탄화규소 저항체를 가열해 얻고, 시료광속이 시료셀을 지나갑니다.","광원은 중수소방전관·중압수은등이며 합산증폭기가 SO2 간섭을 보정한다":"자외선흡수분석계의 광원은 중수소방전관이나 중압수은등이고, 합산증폭기가 SO2 간섭을 보정합니다.","광화학 대기오염에 중요한 것은 900nm 이상의 장파장 빛이 아니다":"광화학 대기오염에서는 900nm 이상의 장파장 빛이 아니라 짧은 파장의 빛이 반응을 일으킵니다.","광화학반응으로 생기며 O3·H2O2·CH3ONO2가 해당한다":"2차 오염물질은 광화학반응으로 생기며 O3, H2O2, CH3ONO2가 해당해요.","광화학반응·침강역전에 의한 사건으로 미국에서 발생했다":"LA스모그는 광화학반응과 침강역전이 원인이며 미국에서 일어난 사건이에요.","교정용 입자는 균일계 단분산 입자를 쓰며 먼지농도 단위는 mg/Sm3다":"교정에는 크기가 고른 단분산 입자를 쓰고 농도는 mg/Sm3로 나타냅니다.","구형입자 비표면적(Sv)은 6/d이며 입경과 반비례 관계다":"6/d로 계산하므로 입경 d가 작을수록 비표면적이 커집니다.","국가대표 훈련용, 주한 외국군인 가족용, 항공기 지상조업용 자동차":"국가대표 훈련용, 주한 외국군인 가족용, 항공기 지상조업용 자동차는 인증을 생략하거나 면제합니다.","국지적 광화학스모그로 생성된 옥시던트의 지표물질이다":"대류권 오존은 국지적 광화학스모그로 생긴 옥시던트를 대표하는 지표물질입니다.","굴뚝 내압이 큰 부압(-300mmH2O 이하)이면 시료채취용 굴뚝을 별도 부설한다":"굴뚝 안이 -300mmH2O 이하로 크게 눌려 있으면 시료채취용 굴뚝을 따로 설치합니다.","굴뚝높이가 2배가 되면 통풍력은 √2배가 아니다":"굴뚝이 두 배 높아져도 통풍력이 √2배 늘어나는 관계는 아닙니다.","굴뚝자동측정기 정도검사 현황은 연1회 보고 항목이 아니다":"굴뚝자동측정기 정도검사 현황은 연 1회 보고하는 항목에 들어가지 않습니다.","규소 방해는 0.5% 인산용액으로 제거하며 0.2% 황산나트륨은 아니다":"철 분석에서 규소의 방해는 0.5% 인산용액으로 없애고, 0.2% 황산나트륨은 쓰지 않습니다.","규제오염물질, 규제구역, 오염물질 저감계획 등이다":"총량규제 고시사항은 규제오염물질, 규제구역, 오염물질 저감계획 등입니다.","극성물질(물)을 잘 흡착하며 175~325℃에서 재생한다":"실리카겔과 활성알루미나는 물 같은 극성물질을 잘 흡착하고 175~325℃에서 재생해요.","극성물질에 유효한 것이 아니라 비극성·유기용제 제거능이 높다":"활성탄은 극성물질에 효과적인 것이 아니라 비극성 물질과 유기용제를 잘 제거합니다.","금속주조업·배합사료제조업·일반도자기제조업은 비산먼지 발생사업에 해당한다":"금속주조업, 배합사료제조업, 일반도자기제조업도 이 사업에 속합니다.","기간·주행거리·가동시간 중 먼저 도달하는 것을 기준으로 한다":"만료 시점은 기간, 주행거리, 가동시간 중 먼저 채워지는 쪽으로 정해집니다.","기름에 석탄을 분쇄·혼합해 계면활성제로 침강을 막는다":"COM은 기름에 석탄을 분쇄해 섞고 계면활성제로 침강을 막은 혼합연료예요.","기술능력현황서, 공정도, 원료·제품 사용량 및 배출량 예측 명세서를 제출한다":"자가방지시설을 낼 때는 기술 인력 현황서, 공정도, 원료·제품 사용량과 배출량 예측표를 붙입니다.","기술능력현황을 기재한 서류는 공동방지시설 허가 제출서류가 아니다":"기술능력현황 서류는 공동방지시설 허가를 받을 때 내는 서류가 아닙니다.","기압경도력과 전향력이 크기는 같고 방향이 반대로 평형을 이룬다":"지균풍에서는 기압경도력과 전향력이 크기가 같고 방향이 반대라 평형을 이룹니다.","기압경도력·전향력·원심력 3가지 힘이 평형을 이뤄 등압선을 따라 분다":"세 가지 힘이 균형을 이룬 채 등압선을 따라 휘어 부는 바람입니다.","기압경도력·전향력·원심력·마찰력이다":"바람에 작용하는 힘은 기압경도력, 전향력, 원심력, 마찰력이에요.","기체·액체연료 특징을 겸비하며 누출시 낮은 곳에 체류해 인화 위험이 크다":"LPG는 기체와 액체연료의 특징을 모두 갖고, 새면 낮은 곳에 고여 인화 위험이 큽니다.","기체흐름에 대한 저항이 큰 것은 좋은 조건이 아니다":"가스가 지나가기 힘들 만큼 저항이 크면 흡착장치에 불리합니다.","기화시 발열량이 느는 것이 아니며, 대부분 석유정제 부산물이 아니라 천연가스에서 얻는다":"기화한다고 발열량이 늘지 않으며, 원료도 정제 부산물보다는 천연가스에서 나옵니다.","납 연간평균기준은 0.5㎍/m3 이하, CO 1시간기준은 25ppm 이하다":"대기환경기준에서 납은 연간평균 0.5㎍/m3 이하, CO는 1시간 기준 25ppm 이하로 정해져 있어요.","납 중독이 아니다(이는 수은 중독 명칭)":"Hunter-Russel 증후군은 납 중독이 아니라 수은 중독을 가리키는 이름입니다.","낮에는 사면류가 골짜기로 모여 곡풍이 가속되며 산 위로 분다(밤엔 반대로 산풍)":"낮에는 사면의 공기가 골짜기에 모여 곡풍이 가속되며 산 위로 불고, 밤에는 반대로 산풍이 불어요.","낮에는 일사량·풍속(지상10m)으로, 밤에는 운량·운고·풍속으로 안정도를 구분한다":"Pasquill 안정도는 낮에는 일사량과 풍속(지상 10m)으로, 밤에는 운량·운고·풍속으로 구분해요.","낮에 시작해 오후 중간쯤 가장 강하며 육풍보다 영향거리가 길다":"해풍은 낮에 시작해 오후 중간쯤 가장 세고, 육풍보다 영향거리가 깁니다.","낮에 육지에서 바다로 부는 것은 해풍이 아니다":"낮에 육지에서 바다 쪽으로 부는 바람은 해풍이라고 하지 않습니다.","낮에 풍속이 약하고(2m/s 이하) 일사량이 강해도 가장 안정한 등급이 되는 것은 아니다":"낮에 바람이 약하고 일사가 강하다고 해서 가장 안정한 등급이 되지는 않습니다.","내압이 정압이라 연소효율이 좋고 송풍기 동력소모가 적다":"연소실 압력이 대기압보다 높아 연소효율이 좋고 송풍기가 쓰는 동력이 적습니다.","내화성산화물 원소에 프로판-공기 불꽃을 쓰는 것은 적당하지 않다":"프로판-공기 불꽃은 내화성산화물 원소를 분석하는 데 알맞지 않습니다.","내화성산화물을 만들기 쉬운 원소는 불꽃온도가 높은 아세틸렌-아산화질소 불꽃으로 분석한다":"내화성산화물이 잘 생기는 원소는 더 뜨거운 아세틸렌-아산화질소 불꽃이 맞습니다.","내화성산화물을 만들기 쉬운 원소 분석에 적합하다":"아세틸렌-아산화질소 불꽃은 내화성산화물을 만들기 쉬운 원소를 분석할 때 알맞아요.","넓은 각도로 조절범위가 좁다":"유압식 버너는 분무각이 넓은 반면 유량 조절범위가 좁다는 특징이 있습니다.","넓이백분율법·보정넓이백분율법·내부표준법·외부표준법이 있다":"GC 정량법에는 넓이백분율법, 보정넓이백분율법, 내부표준법, 외부표준법이 있어요.","노 내부에서 연소가 끝나도록 가스·공기 유속을 결정한다":"포트형 버너는 노 안에서 연소가 끝나도록 가스와 공기의 유속을 정합니다.","농도가 아니라 온도·활성화에너지로 결정된다":"반응속도상수는 농도가 아니라 온도와 활성화에너지로 결정됩니다.","농도·제조법은 3g/100mL가 아니라 다른 지정 비율을 쓴다":"농도는 3g/100mL가 아닌 다른 비율로 만들어 사용합니다.","다공판탑은 대량 흡수액이 필요하거나 고체부유물에 적합한 것이 아니다":"다공판탑은 흡수액이 많이 들거나 고체 부유물이 있는 경우에 어울린다고 하면 틀립니다.","다량 탄소 포함 시료는 여과지를 적당히 잘라 전처리한다":"탄소가 많이 든 시료는 여과지를 알맞게 잘라서 전처리합니다.","다목적첨가제·청정분산제·유동성향상제·옥탄가향상제·세척제":"인정된 첨가제는 다목적첨가제, 청정분산제, 유동성향상제, 옥탄가향상제, 세척제예요.","다이에틸다이티오카바민산은 흡수분광법(흡광광도법)으로 측정한다":"다이에틸다이티오카바민산을 이용해 색의 진하기로 비소를 재는 분석입니다.","다이옥신 처리에 적외선광분해법이나 산성조건 오존분해 촉진은 해당하지 않는다":"적외선광분해법이나 산성 조건에서 오존분해를 촉진하는 것은 다이옥신 처리법이 아닙니다.","다익팬은 저속·저압에, 터보형은 고압·대용량에 쓰인다":"다익팬은 느린 속도와 낮은 압력에, 터보형은 높은 압력과 많은 풍량에 쓰입니다.","단독으로 처리효율이 우수해 쓰이는 것이 아니라 전처리 목적이다":"수세법은 단독 처리용이 아니라 앞단 전처리 용도로 주로 씁니다.","단면적 1m² 이하라고 중심 1점만으로 대표하지는 않는다":"굴뚝 단면이 작아도 중심 한 점만 재서 전체를 대표시키지는 않습니다.","단위는 m3/일이나 m3/min이 아니라 m3/hr다":"유량은 하루나 분 단위가 아니라 시간 단위(m3/hr)로 나타냅니다.","단위밀도(1g/cm3)를 가정한 같은 침강속도의 구형입자 직경이다":"스토크스직경은 단위밀도(1g/cm3)를 가정하고 침강속도가 같은 구형입자의 직경입니다.","담배·앨팰퍼·무는 오존에 강한 식물이 아니라 민감한 식물이다":"담배, 앨팰퍼, 무는 오존에 약해서 가장 먼저 피해를 보는 민감한 식물입니다.","담체는 흡착형 충전물이 아니며, 입경은 120~149나 177~250㎛가 아니다":"담체는 흡착이 일어나는 충전물이 아니며, 입경도 제시된 범위와 다릅니다.","당량비를 낮춰 NOx를 줄이며 고산소연소는 저감법이 아니다":"연료를 희박하게 섞어 당량비를 낮추면 NOx가 줄고, 산소를 늘려 태우는 것은 반대입니다.","대기압 하에서 환원제·산화제 모두로 작용할 수 있다":"이산화황은 보통 대기압에서 다른 물질을 산화시키기도, 환원시키기도 합니다.","대기오염물질의 배출기간, 배출되는 오염물질의 종류도 고려사항이다":"배출된 기간과 오염물질의 종류도 부과금 계산에 함께 반영합니다.","대기와 압력차 100mmHg 이상인 것을 쓴다":"수은 마노미터는 대기와의 압력차가 100mmHg 이상인 것을 씁니다.","대기 중 CO2로 산화되기 어려우며 평균 체류시간은 1~3개월로 추정된다":"CO는 잘 산화되지 않아 대기 중에 평균 1~3개월 머무는 것으로 추정됩니다.","대기 중 부유분진을 10㎛ 이하 입경 기준으로 포집한다":"로우볼륨에어샘플러는 대기 중 부유분진을 10㎛ 이하 입경 기준으로 포집해요.","대기 중 아황산·황산은 석회·대리석·시멘트 등 건축재료를 약화시킨다":"대기 중 아황산과 황산은 석회, 대리석, 시멘트 등 건축재료를 약하게 만들어요.","대기환경기사 이상 1인 이상을 둬야 한다":"1종 사업장은 대기환경기사 이상의 자격을 가진 환경기술인을 1인 이상 둬야 합니다.","대부분 공기역학적직경 2.5㎛ 미만인 입자성 물질이다":"PAH는 공기역학적직경이 2.5㎛보다 작은 입자 형태인 경우가 대부분입니다.","대조화합물로 교정된 기기의 측정값 대비 실제농도 비율이다":"반응인자는 대조화합물로 교정된 기기의 측정값에 대한 실제농도의 비율입니다.","덕트 내가 부압이면 흡인장치를 덕트 밖으로 뺀 후 흡인펌프를 정지시킨다":"덕트 안이 부압이면 흡인장치를 덕트 밖으로 뺀 뒤에 흡인펌프를 멈춥니다.","도관은 짧게 하고 냉각도관은 수직으로 설치한다":"도관을 짧게 하고, 냉각도관은 세워서 달아야 응축수가 빠집니다.","도시는 인공열 발생, 구조물 거칠기 변화로 교외보다 기온이 높다":"도시는 인공열이 나오고 구조물 때문에 지표 거칠기가 달라서 교외보다 기온이 높습니다.","돕슨이며 적도는 약 400, 극지방은 약 200돕슨이다":"오존층 두께는 돕슨 단위로 나타내며 적도는 약 400, 극지방은 약 200돕슨입니다.","동압은 0.1mmH2O 단위까지 읽고 등속계수가 90~110% 범위에 들어야 한다":"동압은 0.1mmH2O까지 읽고, 등속흡인이 잘 됐는지는 90~110% 범위로 판단합니다.","되튐으로 인한 시료손실이 일어날 수 있다":"관성충돌법에서는 입자가 튕겨 나가는 되튐 때문에 시료손실이 생길 수 있습니다.","등가비가 커도 NOx가 늘지 않고, 등가비와 공기비는 비례관계가 아니다":"등가비를 키운다고 NOx가 늘지도 않고, 공기비와 정비례하지도 않습니다.","등압선 간격이 좁을수록 강해지며 고도에 따라 기압은 감소한다":"기압경도력은 등압선 간격이 좁을수록 강해지며 고도가 오르면 기압이 줄어듭니다.","디에틸디티오카바민산나트륨 용액은 제조 후 1개월 이상 지난 것을 쓰지 않는다":"디에틸디티오카바민산나트륨 시약은 만든 지 1개월을 넘기면 못 씁니다.","디에틸아민동 용액에 흡수시켜 435nm에서 흡광도를 측정한다":"디에틸아민동 용액에 흡수시킨 뒤 435nm에서 흡광도를 재어 이황화탄소를 분석합니다.","라돈은 조혈기능·중추신경계에 영향을 미치는 것이 아니다":"라돈이 영향을 주는 곳은 조혈기능이나 중추신경계가 아닙니다.","로듐이 CO·HC 산화를, 백금이 NO 환원을 담당하는 것은 아니다":"로듐이 CO·HC를 산화하고 백금이 NO를 환원한다는 설명은 반대로 쓴 말입니다.","마그네슘법은 습식법, 금속산화물법은 부산물 없는 건식법이다":"마그네슘법은 액체로 씻는 습식 탈황이고, 금속산화물법은 찌꺼기가 남지 않는 건식 탈황입니다.","맑고 바람 약한 밤~새벽에 지표가 식으며 생기고 낮에 소산된다":"복사역전은 맑고 바람이 약한 밤부터 새벽에 지표가 식으며 생겨서 낮에 사라집니다.","맑은 하늘이 푸른 것은 레일리산란 때문이며 청색광이 적색광보다 많이 산란된다":"푸른빛이 붉은빛보다 더 많이 흩어지기 때문에 맑은 하늘이 푸르게 보입니다.","매반기별로 부과하며 월별·분기별 부과가 아니다":"기본부과금은 매 반기마다 부과하며 월별이나 분기별로 부과하지 않아요.","매연발생이 많은 것이 아니라 적다":"분해와 산화가 쉬운 탄화수소는 오히려 매연을 적게 냅니다.","매연의 검은 정도는 6종으로 분류하며 무풍일 때 측정한다":"매연의 검은 정도는 6종으로 분류하며 바람이 없을 때 측정해요.","머무름 현상이 적은 것이 아니라 충전탑보다 체류가 더 크다":"단탑은 가스가 머무르는 시간이 충전탑보다 짧지 않고 더 깁니다.","먼지가 가장 많이 새는 곳이며, 3km 이내 거리는 아니다":"측정위치는 먼지가 가장 많이 새는 곳이며, 3km 이내 거리라는 말은 맞지 않아요.","먼지농도가 너무 낮을 때도 2차전류가 많이 흐를 수 있다":"먼지가 너무 적어도 전류가 커지는 일이 생깁니다.","먼지농도가 너무 높거나 이온이동도가 적은 가스를 처리할 때는 2차전류 과다 원인이 아니다":"먼지가 너무 많거나 이온이 잘 안 움직이는 가스는 2차전류가 과해지는 원인이 아닙니다.","먼지 배출농도 단위는 mg/Sm3, 일반오염물질 초과배출량은 소수점 첫째자리까지 계산한다":"먼지는 mg/Sm3로 나타내고, 일반오염물질 초과배출량은 소수 첫째 자리까지 구합니다.","메탄올·아세톤이 아니라 노말헥산으로 세정한 것을 쓴다":"증류수 대신 노말헥산으로 씻은 것을 사용해야 하며, 메탄올이나 아세톤은 쓰지 않습니다.","메탄은 프로판보다 이론공기량이 적다":"메탄은 프로판보다 단위부피당 이론공기량이 적어요.","메틸에틸케톤·프로피온산·뷰틸아세테이트도 지정악취물질에 포함된다":"메틸에틸케톤, 프로피온산, 뷰틸아세테이트까지 지정악취물질 목록에 있습니다.","면적합계 3000㎡ 조경공사와 석유정제업":"면적 합계 3000㎡의 조경공사와 석유정제업은 신고 대상에서 빠집니다.","모노클로로벤젠·에틸벤젠이 있으면 측정치가 높아진다":"모노클로로벤젠이나 에틸벤젠이 섞여 있으면 벤젠 측정치가 높게 나옵니다.","모든 지하역사는 실내공기질법 적용대상이다":"지하역사는 규모와 상관없이 모두 실내공기질법 적용대상이에요.","무부하 흡인유량은 5~10m3/min나 0.5m3/hr가 아니라 약 2.0m3/min이다":"무부하일 때 빨아들이는 유량은 약 2.0m3/min으로 정해져 있습니다.","무색무취 기체로 액화돼도 색이 없으며 화학반응을 거의 하지 않는다":"라돈은 무색무취 기체로 액체가 돼도 색이 없고 화학반응을 거의 하지 않아요.","무신고 조업, 측정기기 관리업 무등록 대행은 1년 이하 징역·1천만원 이하 벌금이다":"신고 없이 조업하거나 측정기기관리업을 등록 없이 대행하면 1년 이하 징역 또는 1천만원 이하 벌금입니다.","물과 수산화나트륨에 피로갈롤을 녹인 용액이다":"산소흡수액은 물과 수산화나트륨에 피로갈롤을 녹여 만들어요.","물리흡착의 흡착열은 피흡착물 증발열보다 낮지 않고 비슷한 수준이다":"물리흡착의 흡착열은 피흡착물의 증발열보다 낮은 것이 아니라 비슷한 수준입니다.","물에 난용성이어서 강우 영향을 거의 받지 않는다":"CO는 물에 잘 녹지 않아서 강우의 영향을 거의 받지 않습니다.","물에 대한 용해도가 커 수세 처리가 적당하다":"불소화합물은 물에 대한 용해도가 커서 수세로 처리하기 알맞아요.","물에 불용이며 증기압이 높은 물질일수록 악취가 강하다":"메르캅탄류는 물에 녹지 않고 증기압이 높은 물질일수록 악취가 강해요.","물질 1g을 1℃ 올리는 데 필요한 열량이며 상태함수가 아니라 경로에 좌우된다":"비열은 물질 1g을 1℃ 올리는 데 드는 열이고, 경로에 따라 값이 달라지는 양입니다.","뮤즈계곡(벨기에)·도노라(미국)·런던스모그":"황산화물이 주원인인 대기오염 사건으로 벨기에, 미국, 영국의 사례가 있습니다.","미립화(무화) 특성은 분무유량·분무입경·분무도달거리로 결정된다":"분무하는 양, 방울 크기, 분무가 닿는 거리가 미립화 정도를 가르는 요소입니다.","미분적이고 DOAS가 적분적인 것이 아니라 그 반대다":"일반 흡광광도법이 미분적이고 DOAS가 적분적인 것이 아니라 그 반대예요.","미세먼지는 입자크기 1.0㎛ 이하가 아니고, 오존 1시간기준도 0.06ppm이 아니다":"미세먼지와 오존의 환경기준값은 이 문장에 나온 수치와 다르다는 뜻입니다.","미세입자 특성과 잘 일치하지 않는다":"대수정규분포는 미세입자의 특성과 잘 맞지 않아요.","미연탄소·재 방출이 최소화되지 않으며, 유동사는 활성이 낮아야 한다":"유동층 연소에서 미연탄소와 재 방출이 최소화되는 것은 아니며, 유동사는 활성이 낮아야 합니다.","미지성분과 예측물질의 보유시간(머무른값)을 비교해 확인한다":"미지 성분의 머무른 시간과 후보 물질의 머무른 시간을 맞대어 어떤 물질인지 정합니다.","밀도를 고려해 침강속도가 같은 구형입자 직경으로 정의한다":"공기역학적직경은 밀도를 고려해 침강속도가 같은 구형입자의 직경으로 정의합니다.","밀도 큰 가스출구는 상부가 아니라 하부, 공기출구는 하부가 아니라 상부다":"밀도가 큰 가스는 아래로, 공기는 위로 빼야 하므로 출구 위치가 반대로 정해집니다.","밀도·형상계수 등 변수가 이미 반영돼 따로 중요시되지 않는다":"공기역학적직경에는 밀도와 형상계수 같은 변수가 이미 반영돼 있어 따로 따지지 않아요.","밀폐공간 유해환경 노출로 눈자극·두통 등을 일으킨다":"닫힌 공간에서 오염된 공기를 마시면 눈이 따갑고 머리가 아픈 빌딩증후군이 생깁니다.","밀폐통이 아니라 덮개 있는 차량으로 운반한다":"석탄연소재는 밀폐통이 아니라 덮개를 씌운 차량으로 운반해요.","바깥벽으로부터 1.5m 이상 떨어진 곳에서 채취한다":"건물이 밀집한 곳에서는 바깥벽에서 1.5m 이상 떨어진 곳에서 채취합니다.","바다에서 육지로 분다(비열차에 의해 발생)":"해풍은 바다에서 육지로 불며, 땅과 바다의 비열 차이가 원인입니다.","바람·눈·비를 피해 측정기기는 실내에 두고 채취구만 밖으로 연결한다":"비바람과 눈을 피하려고 장비는 실내에 두고 채취구만 밖으로 이어 놓습니다.","반감기 3.8일이며 공기보다 무거워 지표 가까이 존재하고 폐암 원인이 된다":"라돈의 반감기는 3.8일이고 공기보다 무거워 지표 가까이 있으며 폐암의 원인이 됩니다.","반응경로와 무관하며 물질의 양에 비례한다":"엔탈피는 반응경로와 상관없이 정해지고 물질의 양에 비례하는 값이에요.","반응물이 생성물보다 에너지가 높으면 발열반응이며, 흡열반응이 엔탈피 감소를 뜻하는 것은 아니다":"반응물 에너지가 더 높아 생성물로 가며 열이 나오면 발열반응이고, 흡열은 그 반대입니다.","반응온도에 따라 종모양(Bell-shape) 곡선을 보인다":"SCR의 전환율은 반응온도에 따라 종 모양(Bell-shape) 곡선을 그립니다.","발색액은 청색이 아니라 적색계열이며 610nm가 아닌 다른 파장에서 측정한다":"붉은 계열 색이 나며 610nm가 아닌 다른 파장에서 흡광도를 잽니다.","발생량 합계 80톤 이상 시설은 주 1회 이상, 10~20톤은 매 2월 1회 측정한다":"발생량 합계 80톤 이상은 매주 이상, 10~20톤은 두 달에 한 번 재야 합니다.","발암성은 청석면>아모사이트>온석면 순이며 우라늄·라듐이 라돈의 발생원이다":"석면 발암성은 청석면, 아모사이트, 온석면 순이고, 우라늄과 라듐이 라돈의 발생원입니다.","발열량·연료비는 증가하고 매연발생율·연소속도는 감소한다":"탄화도가 높아지면 발열량과 연료비는 늘고 매연발생율과 연소속도는 줄어듭니다.","발열량은 측정위치가 아니라 수증기 응축 포함 여부로 고위·저위가 나뉜다":"고위와 저위는 측정 위치가 아니라 수증기 응축열을 포함하느냐로 나뉩니다.","발열량이 낮을수록, 분자량이 작을수록 높아진다":"발열량이 낮고 분자량이 작은 연료일수록 불이 붙는 온도가 높습니다.","발열량·인화점·착화점은 낮아진다":"비중이 커진 석유는 발열량, 인화점, 착화점이 낮아집니다.","발열반응 화재 대비는 온도센서 감시만으로 충분한 것은 아니다":"발열반응으로 인한 화재에 대비하려면 온도센서 감시만으로는 충분하지 않습니다.","발전소 배출시설 과징금은 900만원·600만원이 아니라 300만원이다":"발전소 배출시설의 과징금은 다른 금액이 아니라 300만원으로 정해져 있습니다.","방사경사형·비행기날개형(에어포일형)은 축류형이 아니라 원심형이다":"방사경사형이나 에어포일형은 축류형이 아니라 원심형 송풍기입니다.","방사선식 여기법은 γ선이 아니라 형광X선의 강도를 측정한다":"방사선식 여기법이 재는 것은 γ선이 아니라 형광X선의 강도입니다.","방사선을 조사해 형광X선 강도로 황함유량을 측정한다":"방사선식 여기법은 시료에 방사선을 쬐어 나오는 형광X선의 세기로 황함유량을 잽니다.","방사성물질(Ni-63·삼중수소)의 β선으로 운반기체를 전리해 검출한다":"ECD는 방사성물질(Ni-63, 삼중수소)이 내는 β선으로 운반기체를 전리시켜 검출합니다.","방전극이 굵고 짧을수록 코로나 방전이 쉬운 것이 아니라 가늘고 길수록 쉽다":"방전극은 굵고 짧을수록이 아니라 가늘고 길수록 코로나 방전이 쉽습니다.","방지시설 일반도·유지관리계획서·설치내역서 등":"설치신고서에는 방지시설 일반도, 유지관리계획서, 설치내역서 등을 첨부해요.","방진덮개로 덮고 함수율 7~10% 유지용 살수시설을 설치한다":"야적물질은 방진덮개로 덮고, 함수율 7~10%를 유지하도록 살수시설을 설치해요.","방진망은 저장높이 1.5배가 아니며, 보관시설은 4면이 아니라 3면이 막힌 구조다":"방진망 높이는 저장높이의 1.5배가 아니며, 보관시설은 세 면만 막힌 구조입니다.","방향전환 각도가 클수록 좋은 것은 아니며, 고온가스 처리가 불가능한 것도 아니다":"방향전환 각도가 크다고 더 좋은 것은 아니며, 뜨거운 가스도 처리할 수 있습니다.","배출가스를 분명히 관측 가능한 1km 이내 거리에 위치한다":"측정자는 배출가스를 분명히 볼 수 있는 1km 이내 거리에 서야 해요.","배출구에서 30~40m 떨어진 곳이 아니라 16m 떨어진 곳에서 눈높이로 관측한다":"배출구에서 16m 떨어진 곳에서 눈높이로 보며, 30~40m는 기준이 아닙니다.","배출·방지시설 운영기록은 사실대로 작성하고 배출허용기준에 맞게 정상가동해야 한다":"환경기술인은 배출·방지시설 운영기록을 사실대로 쓰고 배출허용기준에 맞게 정상가동해야 해요.","배출·방지시설 운영일지는 최종기재일로부터 1년간 보존해야 한다":"운영일지는 마지막으로 쓴 날부터 1년 동안 보관합니다.","배출시 2·3·5종도 더 엄격한 기준을 적용한다":"특정대기유해물질을 배출하면 2종, 3종, 5종 사업장도 더 엄격한 기준을 적용받아요.","배출시설의 공정도·도면이나 위치·운영 규약은 이 서류 목록이 아니다":"배출시설의 공정도와 도면, 위치와 운영 규약은 이 서류 목록에 들어가지 않아요.","배출시설 폐쇄, 동종·동일규모 대체, 사업장 명칭 변경":"변경신고 사항에는 배출시설 폐쇄, 동종·동일규모 대체, 사업장 명칭 변경이 있습니다.","배출원에서 직접 나온 것으로 HCl·HC·NaCl·SO2가 해당한다":"배출원에서 바로 나온 염화수소, 탄화수소, 염화나트륨, 아황산가스가 일차 오염물질입니다.","배출허용기준 초과사유·대책은 개선계획서 포함사항이 아니다":"초과한 이유와 그 대책은 개선계획서에 적을 내용에 포함되지 않습니다.","배출허용기준 초과여부를 고려해 부과한다":"배출부과금은 배출허용기준을 넘었는지를 고려해 부과해요.","배출허용농도는 5·15mg/Sm3이 아니라 10mg/Sm3 이하다":"아연화합물은 5나 15가 아닌 10mg/Sm3 이하를 배출허용농도로 삼습니다.","백금(Pt)이 CO·HC 산화를, 로듐(Rh)이 NOx 환원을 주로 담당한다":"백금은 CO와 HC를 산화시키고, 로듐은 NOx를 환원시키는 역할을 맡습니다.","백금계 촉매로 CO를 산화 제거하며 황(S)·비소(As) 화합물이 촉매독으로 작용한다":"백금계 촉매는 CO를 산화시켜 없애고, 황 화합물과 비소 화합물은 촉매를 망가뜨리는 촉매독입니다.","백금·금속산화물 촉매로 260~350℃에서 산화 처리한다":"백금이나 금속산화물 촉매를 쓰면 260~350℃의 비교적 낮은 온도에서 악취가 산화됩니다.","백금·코발트는 바람직하지 않은 촉매가 아니며, Ni(니켈)은 촉매독이 아니다":"백금과 코발트는 쓸 수 있는 촉매이고, 니켈(Ni)은 촉매독이 아닙니다.","버너 내에서 연료·공기를 미리 혼합해 공급하는 방식이 아니다":"확산연소는 버너 안에서 연료와 공기를 미리 섞어 보내는 방식이 아니라 밖에서 섞이며 타는 방식입니다.","벌금이 7년/7천만원이나 5년/5천만원, 과태료가 500만원·300만원인 것은 아니다":"벌금 7년/7천만원, 5년/5천만원, 과태료 500만원, 300만원은 해당하지 않습니다.","베릴륨화합물·1,3-부타디엔도 특정대기유해물질에 포함된다":"베릴륨화합물과 1,3-부타디엔도 법에서 지정한 유해물질 목록에 들어갑니다.","벤젠을 니트로화해 자색액 흡광도로 정량한다":"벤젠을 니트로화하여 생긴 자색 용액의 흡광도로 정량하는 방법이에요.","벤젠 폭로로 인한 백혈병은 주로 급성골수아성백혈병(AML)이다":"벤젠에 노출되어 생기는 백혈병은 주로 급성골수아성백혈병(AML) 유형입니다.","벤츄리·제트·스프레이타워 스크러버가 있다":"가압수식 스크러버에는 벤츄리, 제트, 스프레이타워 스크러버가 있습니다.","변경신고를 하지 않으면 100만원 이하 과태료를 부과한다":"변경신고를 빠뜨리면 100만원 이하의 과태료가 따릅니다.","보유시간 오차범위는 ±5%가 아니다":"머무른 시간의 허용 오차는 ±5%가 아닌 다른 범위입니다.","보유시간은 3회 측정해 평균치를 구한다":"보유시간은 3회 측정해 평균값을 구해요.","보육시설은 연면적 430㎡ 이상, 의료기관은 연면적 2천㎡ 이상(병상 100개 이상)이 대상이다":"보육시설과 의료기관은 연면적이 일정 규모 이상일 때만 실내공기질법 적용 대상입니다.","보정치의 80%·90%가 아니라 다른 지시치 도달시간 기준이다":"응답시간은 보정치의 80%나 90%가 아니라 다른 지시치에 도달하는 시간을 기준으로 해요.","보존기간은 1년·2년이 아니다":"보존해야 하는 기간은 1년이나 2년이 아니라 별도로 정해진 기간입니다.","보존기간이 3개월·6개월이거나 과태료가 1000만원·500만원인 것은 아니다":"보존기간을 3개월이나 6개월로 보거나 과태료를 1000만원, 500만원으로 보면 틀립니다.","보증기간은 5년 또는 80000km다":"경유 경자동차의 배출가스 보증기간은 5년 또는 80000km입니다.","보통 100~200℃ 범위에서 최대가 되며 수분이 늘면 최대점이 고온측으로 이동한다":"전기집진에서 비저항은 보통 100~200℃에서 최대가 되고, 수분이 늘면 최대점이 고온 쪽으로 옮겨갑니다.","보통 7~16%이며 점도 기준으로 3종으로 분류된다":"중유의 잔류탄소분은 보통 7~16%이고 점도를 기준으로 3종으로 분류합니다.","보통강철은 부적합하며, 톨루엔·크실렌은 측정치를 낮추지 않는다":"보통강철은 채취관 재질로 맞지 않고, 톨루엔과 크실렌이 측정치를 낮추지도 않아요.","복사(방사성)역전에 해당하며 SOx가 주원인이다":"런던형 스모그는 복사(방사성)역전에 해당하며 SOx가 주원인입니다.","부유물 포함 흡수액에 유리하다":"단탑(Plate Tower)은 부유물이 들어 있는 흡수액에 유리합니다.","부피비 99% 이상이 메탄으로 구성된다":"LNG는 부피비 99% 이상이 메탄으로 이루어져 있어요.","부하변동범위가 넓고 연소조절이 용이하다":"기체연료는 부하변동범위가 넓고 연소조절이 쉬운 편이에요.","북반구 고기압에서 시계반대방향으로 부는 것은 아니다":"북반구 고기압에서 경도풍이 반시계 방향으로 분다는 설명은 맞지 않습니다.","북반구에서 기압경도력이 감소해 반시계방향으로 부는 것은 아니다":"북반구에서 기압경도력이 줄어서 반시계로 부는 바람은 지균풍이 아닙니다.","북반구에서는 운동방향의 오른쪽으로 작용하며 위도가 높을수록 커진다":"북반구 기준으로 운동하는 방향의 오른쪽으로 힘이 작용하고, 위도가 높을수록 세집니다.","분리관 내경 3mm일 때 흡착제·담체 입경범위는 149~177㎛다":"분리관 내경이 3mm이면 담체와 흡착제 입경은 149~177㎛ 범위를 씁니다.","분말금속아연으로 아질산이온으로 환원해 분석하며 10~1000V/Vppm에 적당하다":"분말 아연으로 아질산이온까지 환원한 뒤 재며, 10~1000V/Vppm 농도에 맞습니다.","분무각 45~90°이고 회전수는 5000~6000rpm이다":"회전식 버너는 분무각이 45~90°이고 분무컵을 5000~6000rpm으로 돌려 기름을 퍼뜨립니다.","분무액과 가스 접촉은 균일한 것이 아니라 불균일해 효율이 낮은 편이다":"분무액과 가스의 접촉은 균일하지 않아서 효율이 낮은 편입니다.","분무점도는 미립화 특성을 결정하는 직접 인자로 보지 않는다":"분무점도는 무화 특성을 직접 정하는 요인으로 꼽지 않습니다.","분무탑은 침전물 발생 경우에, 벤츄리스크러버는 점착성·조해성 먼지에 적합하다":"분무탑은 침전물이 생길 때, 벤츄리스크러버는 끈적이고 습기를 빨아들이는 먼지에 알맞습니다.","분산모델은 장기 분석이 아니라 단기 분석에 적합하다":"분산모델은 장기 분석이 아니라 단기 분석에 알맞은 방법이에요.","분석기는 분광기·샘플채취부·검지부로, 광원부는 발광부·수광부·광케이블로 구성된다":"분석기와 광원부로 나뉘고, 분석기에는 분광기, 샘플채취부, 검지부가 있습니다.","분석성분을 완전히 분리하고 화학적으로 안정·성분이 일정해야 한다":"GC 고정상액체는 분석성분을 완전히 분리하고 화학적으로 안정하며 성분이 일정해야 해요.","분석용 시료용액을 황산으로 적정하는 것이 핵심 원리다":"시료 용액을 황산으로 적정하여 양을 구하는 것이 이 분석의 원리입니다.","분자 내 수산기 수가 1개일 때 냄새가 가장 강하고 늘어나면 약해진다":"냄새물질은 분자 안의 수산기가 1개일 때 냄새가 가장 강하고, 늘어나면 약해집니다.","분자량 46, 비중 약 1.6이며 420nm 이상 빛에 광분해된다":"분자량 46, 비중 약 1.6이며 420nm가 넘는 빛을 받으면 광분해됩니다.","분자 운동속도는 빠르고 평균자유행로는 짧은 것이 아니라 길다":"열권에서는 분자가 빠르게 움직이고 평균자유행로는 짧지 않고 깁니다.","분자응집력에 좌우돼 온도가 오르면 낮아진다":"액체는 분자끼리 끌어당기는 힘이 점도를 정하고, 온도가 오르면 약해집니다.","분진 재비산이 적어 집진율이 높다":"간헐식은 먼지가 다시 날리는 일이 적어서 집진율이 높습니다.","분진 친수성이 작고 입경이 작을수록 액가스비가 커진다":"분진이 물과 잘 안 어울리고 입경이 작을수록 액가스비를 크게 잡아야 합니다.","불꽃이 청색으로 보이는 부분은 연소속도가 느린 것이 아니다":"푸르게 보이는 부분이 연소가 느린 곳이라는 설명은 맞지 않습니다.","불꽃진행거리를 길게 하는 것은 노킹방지법이 아니다":"시약은 암모니아수, 질산칼륨표준액, 과산화수소수이고 이소프로필알코올은 제외입니다.","불소수지관·구리관 등 부식되지 않는 재질을 쓴다":"시료채취관은 불소수지관이나 구리관처럼 부식되지 않는 재질을 씁니다.","불소수지 도관 내열온도나 도관 길이 100m 기준은 사실과 다르다":"불소수지 도관의 내열온도나 100m 길이 기준은 근거가 없는 수치입니다.","불완전연소로 매연·CO가 늘고 연소효율이 떨어진다":"공기가 모자라면 덜 타서 매연과 CO가 늘고 연소효율이 떨어집니다.","불용성 황산염 생성 금속·산 발생원소가 있으면 전처리가 필요하다":"연소관식 공기법은 불용성 황산염을 만드는 금속이나 산을 내는 원소가 있으면 전처리가 필요해요.","비극성 유기용제 회수·악취제거·가스정화에 쓰인다":"활성탄은 비극성 유기용제 회수, 악취 제거, 가스 정화에 쓰입니다.","비말동반 위험이 있으며 액가스비는 보통 10~50L/m3 수준이다":"분무탑은 물방울이 가스에 딸려 나가는 비말동반 위험이 있고 액가스비는 보통 10~50L/m3 수준이에요.","비분산적외선법·이온전극법으로 측정한다":"염화수소는 비분산적외선법과 이온전극법으로 측정해요.","비분산적외선법 정량범위는 0~250ppm부터 0~1%까지다":"이 방법은 아주 낮은 농도부터 퍼센트 단위까지 폭넓게 재는 장비입니다.","비분산적외선분석법·정전위전해법·가스크로마토그래프법(FID)":"CO 측정법에는 비분산적외선분석법, 정전위전해법, 가스크로마토그래프법(FID)이 있습니다.","비산먼지 미신고 1차 과태료는 200만원이 아니며, 이륜차검사명령 불이행도 해당 없다":"비산먼지 미신고의 1차 과태료 금액은 200만원과 다르고, 이륜차 건은 이 벌칙 밖입니다.","비열이 반응조건과 무관한 상수로 취급되는 것은 아니다":"비열을 반응조건과 상관없는 상수로 취급하는 것은 아닙니다.","비저항이 높을 때 건식집진기나 NH3 주입이 대책은 아니다(수분·SO3 주입)":"비저항이 높을 때 건식집진기를 쓰거나 NH3를 주입하는 것은 대책이 아니며, 수분과 SO3를 주입합니다.","비점은 약 80℃이며 체내흡수는 대부분 호흡기를 통해 이뤄진다":"끓는점이 약 80℃이고 몸에는 주로 숨 쉬면서 흡수됩니다.","비중이 커짐(API도 낮아짐)":"석유는 비중이 커지면 API도가 낮아지는 반비례 관계에 있습니다.","비중이 클수록 유동점·점도가 감소하는 것은 아니다":"비중이 클수록 점도와 유동점이 내려간다고 하면 틀립니다.","빠른 공기움직임에서 비산하는 경우(분쇄기 등) 영향이 작다고 보는 것은 아니다":"공기가 빠르게 움직여 흩날리는 분쇄기 같은 경우에도 영향이 작다고 볼 수 없습니다.","사업자가 스스로 방지시설을 설계·시공할 때 필요한 서류다":"스스로 설계하고 시공하는 사업자가 방지시설을 설치하려고 낼 서류입니다.","사업장-공동방지시설 연결관 설치도면·명세서, 운영규약도 제출한다":"사업장과 공동방지시설을 이은 관의 도면, 명세서, 운영규약을 함께 제출합니다.","사업장 부지경계선을 벗어나는 시설을 말한다":"이동식은 사업장 부지 경계를 벗어나 옮겨 다니는 시설을 가리킵니다.","사업장 운영현황은 배출부과금 부과시 고려사항이 아니다":"사업장이 어떻게 운영되는지는 배출부과금을 매길 때 따지는 항목이 아닙니다.","사용기간·재생능력이 클수록 좋다":"흡착제는 사용기간이 길고 재생능력이 클수록 좋아요.","사용 시료도 저온회화법으로 처리한다":"셀룰로오스섬유제 여과재로 채취한 시료도 저온회화법으로 전처리해요.","사용시 분무노즐 막힘에 주의하며 처리중 고형물이 자주 생긴다":"스프레이탑을 쓸 때는 분무노즐이 막히지 않게 신경 써야 하고 처리 중 고형물이 자주 생깁니다.","사용온도에서 증기압이 낮고 점성이 작아야 한다":"고정상액체는 사용온도에서 증기압이 낮고 점성이 작아야 합니다.","사회복지시설·공공주택 냉난방시설, 의료기관 배출시설도 부과대상이다":"사회복지시설과 공공주택의 냉난방시설, 의료기관 배출시설에도 과징금을 부과해요.","산성비는 pH 5.6 이하이며, 다이옥신·중금속이 주원인은 아니다":"pH 5.6 이하인 비를 산성비라 하고, 다이옥신이나 중금속이 주된 원인은 아닙니다.","산성조건에서 N/100 NaOH로 적정하는 것은 아니며, 적용농도도 임의로 고정된 것은 아니다":"산성 조건에서 N/100 NaOH로 적정하는 방법이 아니며, 적용 농도도 정해진 틀이 없습니다.","산소농도·압력이 높을수록, 비표면적이 클수록 낮아진다":"산소가 많고 압력이 높거나 표면적이 넓을수록 더 낮은 온도에서 불이 붙습니다.","산소함량은 2.3무게% 이하이며, 여름철(6~8월) 증기압은 65kPa 이하다":"산소는 2.3무게% 이하여야 하며, 6~8월 여름철 증기압 상한은 65kPa입니다.","산화성·환원성 가스 영향이 무시될 수 있는 경우에 적당하다":"산화성·환원성 가스의 영향을 무시할 수 있는 경우에 알맞은 방법이에요.","상대습도 50% 이하 기준이 아니라 다른 습도 범위를 요구한다":"상대습도가 50% 이하여야 한다고 못 박지 않고 다른 범위를 요구합니다.","상온에서 무색·자극성 기체이며 비중 약 1.03, 물에 잘 녹아 15% 수용액이 포르말린이다":"무색에 자극성이 있는 기체이고, 비중 약 1.03이며 물에 녹은 15% 수용액을 포르말린이라 부릅니다.","상자 내 오염물 농도는 균일하며 수직단면 바람속도가 일정해 환기량이 일정하다":"상자 안 농도가 어디서나 같고 바람속도가 일정해, 환기되는 양도 일정하다고 가정합니다.","새로운 오염원이 생기면 매번 재평가해야 하며 지형·기상조건 영향을 받는다":"분산모델은 새 오염원이 생기면 매번 다시 평가해야 하고 지형과 기상조건의 영향을 받습니다.","생성물의 생성엔탈피 합에서 반응물의 합을 뺀 값이다":"생성물의 생성엔탈피를 모두 더한 값에서 반응물의 합을 빼면 반응엔탈피입니다.","생활력 왕성한 초엽에 피해가 크며 잎 밑부분이 은백색·청동색이 된다":"PAN은 생활력이 왕성한 초엽에 피해가 크고, 잎 밑부분이 은백색이나 청동색으로 변합니다.","서모스탯감시장치·연료계통감시장치가 포함된다":"자기진단장치(OBD)에는 서모스탯감시장치와 연료계통감시장치가 포함됩니다.","석면먼지 농도는 표준상태 기체 중 석면섬유 개수로 나타낸다":"석면먼지는 공기 속 석면섬유를 개수로 세어 농도로 삼습니다.","석면섬유 광굴절률은 약 1.5로 보통현미경이 아닌 위상차현미경으로 식별한다":"석면은 굴절률이 약 1.5여서 위상차현미경으로 가려내야 합니다.","석면의 공업적 소비는 각섬석계열이 95%가 아니라 사문석계열이 대부분이다":"석면은 각섬석계열이 95%가 아니라 사문석계열이 공업적으로 가장 많이 쓰입니다.","석탄·기름·쓰레기 등의 불완전연소로 형성되며 고리형 구조로 암을 유발한다":"석탄이나 쓰레기 같은 것이 덜 탈 때 생기며, 고리 구조가 암의 원인이 됩니다.","석탄분말에 물을 혼합한 연료로 COM과 함께 석탄슬러리 연료로 분류된다":"석탄 가루에 물을 섞은 CWM은 COM과 함께 석탄슬러리 연료 범주에 듭니다.","석탄 비중은 탄화도가 진행돼도 작아지지 않으며 중유 유동점·잔류탄소도 줄지 않는다":"탄화가 진행돼도 석탄 비중이 줄지 않고, 중유의 유동점과 잔류탄소도 줄지 않습니다.","석탄은 옥내저장시설(밀폐형 포함) 또는 지하저장시설에 저장한다":"석탄은 밀폐형을 포함한 옥내저장시설이나 지하저장시설에 저장해야 합니다.","석회석으로 하면 탈황이 가능하고 저품질 연료도 연소 가능하다":"유동매체를 석회석으로 하면 탈황이 되고, 품질이 낮은 연료도 태울 수 있습니다.","석회석 주입법, 활성산화망간법, 암모니아법은 SO2를 90% 수준까지 제거한다":"이 세 방법은 황산화물을 90% 근처까지 떼어 낼 수 있는 고효율 처리법입니다.","설비비는 비싸며, 소규모가 아니라 대형·대용량 설비에 적합하다":"미분탄 연소설비는 비용이 비싸고, 소규모가 아니라 대형 대용량 설비에 알맞아요.","설치완료신고나 설치허가신청과 동시에 임명신고하는 것은 아니다":"설치가 끝난 신고나 허가 신청 때 함께 임명신고하는 것이 아닙니다.","성층권은 산소분자가 자외선에 광분해되며 오존 생성·소멸이 반복된다":"성층권에서 산소분자가 자외선에 쪼개지며 오존이 만들어지고 사라지는 일이 거듭됩니다.","셀룰로오스에스테르 재질, 구멍지름 평균 0.01~10㎛이다":"멤브레인필터는 셀룰로오스에스테르 재질이고 구멍지름은 평균 0.01~10㎛입니다.","소각능력 시간당 25kg 이상, 분쇄시설 20마력 이상(습식·이동식 제외)":"소각능력이 시간당 25kg 이상이거나 분쇄시설이 20마력 이상이면 배출시설입니다.","소량 액량으로 고농도 가스도 처리 가능하다":"가스분산형 흡수장치는 적은 액량으로도 농도가 높은 가스를 처리할 수 있습니다.","소멸계수(Extinction Coefficient), Coefficient of Haze 등이다":"소멸계수와 Coefficient of Haze가 가시도를 나타내는 용어입니다.","속도상수 단위는 S⁻¹이며 반응속도상수는 온도의 영향을 받는다":"농도에 상관없이 일정한 비율로 줄어드는 반응의 속도상수는 시간의 역수 단위를 가집니다.","손실 없이 채취 가능한 안전농도에 대한 공기부피다":"시료를 잃지 않고 안전하게 뽑을 수 있는 농도에 해당하는 공기 부피를 말합니다.","송풍기는 원심형과 축류형으로 나뉘며 프로펠러형이 축류형에 해당한다":"원심형과 축류형으로 가르며, 프로펠러형은 축류형 쪽에 듭니다.","송풍기·후드장치·관로 등 부대 기계·기구류도 방지시설에 포함된다":"송풍기, 후드장치, 관로 같은 부대 기계와 기구류도 대기오염 방지시설에 포함됩니다.","수분량이 증가할수록 비저항은 감소하며 비저항이 큰 분진은 제거가 어렵다":"습도가 올라가면 비저항이 내려가고, 비저항이 큰 먼지는 걷어 내기가 어렵습니다.","수분 많고 발열량 낮은 쓰레기도 어느 정도 소각 가능하다":"경사스토커는 수분이 많고 발열량이 낮은 쓰레기도 어느 정도 태울 수 있어요.","수분·여과속도에 대한 적응성이 높은 것이 아니라 낮다":"여과집진장치는 수분과 여과속도에 대한 적응성이 높은 것이 아니라 낮습니다.","수분 응축 방지 가열처리는 시료채취관이 아니라 다른 부위에서 한다":"수분이 맺히지 않도록 하는 가열은 채취관이 아닌 다른 부분에서 합니다.","수산화나트륨 0.4g을 물 100mL에 녹인 것을 쓴다":"브롬화합물의 흡수액은 수산화나트륨 0.4g을 물 100mL에 녹인 용액이에요.","수산화나트륨용액에 흡수시키는 방법은 알데히드·케톤 분석법이 아니다":"수산화나트륨용액에 흡수시키는 분석은 알데히드나 케톤 시험법에 들지 않습니다.","수산화칼륨(포타슘) 용액을 쓴다":"탄산가스는 수산화칼륨 용액에 흡수시켜 재는 것이 쓰이는 방법입니다.","수소화탈황법은 이 90% 제거 방법에 포함되지 않는다":"수소화탈황법은 아황산가스를 90%까지 떼어 내는 방법 목록에 들지 않습니다.","수온변화로 탈취효과가 변동하고 압력손실이 크며 주로 전처리로 쓰인다":"수온이 변하면 탈취효과가 달라지고 압력손실이 크며 주로 전처리로 쓰입니다.","수용체 입장에서 영향평가가 가능하고 지형·기상정보 없이도 쓸 수 있다":"수용모델은 수용체 입장에서 영향을 평가할 수 있고 지형과 기상정보 없이도 쓸 수 있습니다.","수증기 증발잠열은 이용이 어려워 실무는 저위발열량을 주로 쓴다":"수증기의 증발잠열은 이용하기 어려워서 실제로는 저위발열량을 주로 씁니다.","수직굴뚝 가스상물질 측정위치는 상부 끝단에서 아래로 상부내경 배수 이상 떨어진 곳이다":"가스는 굴뚝 위 끝에서 아래로 상부내경의 배수만큼 떨어진 곳에서 측정합니다.","수직굴뚝 측정공은 하부 끝단에서 내경 8배 이상 위에 둔다":"수직 굴뚝에서는 아래 끝에서 내경의 8배 이상 올라간 곳에 측정구를 뚫습니다.","순도 99.8% 아르곤이 아니라 다른 지정 가스를 쓴다":"TCD 운반가스는 순도 99.8% 아르곤이 아니라 다른 지정 가스를 씁니다.","스테인리스강·경질유리·석영유리로 만들며 꼭지점은 30° 이하 예각이다":"흡인노즐은 스테인리스강, 경질유리, 석영유리로 만들고 꼭지점은 30° 이하 예각이에요.","스테인리스강 재질로 응축방지 가열이 가능해야 한다":"채취관과 도관은 스테인리스강 재질이어야 하고 응축을 막도록 가열할 수 있어야 해요.","스티렌은 생선취가 아니며, Paraffin·CS2는 적외선을 강하게 흡수하지 않는다":"스티렌은 생선 비린내를 내는 물질이 아니고, 파라핀과 이황화탄소는 적외선을 강하게 흡수하지 않습니다.","스틸렌(스티렌)·바나듐·아크롤레인":"스틸렌, 바나듐, 아크롤레인은 특정대기유해물질 목록에 없는 물질입니다.","스팀이나 불활성가스를 쓰며 스팀은 흡기 반대방향으로 주입한다":"재생에는 스팀이나 불활성가스를 쓰며, 스팀은 흡기와 반대방향으로 넣어요.","습식탈질법은 아질산염·질산염 처리가 용이한 것이 아니라 어렵다":"습식탈질법은 아질산염과 질산염을 처리하기 쉬운 것이 아니라 어렵습니다.","시도지사는 비산먼지 억제시설 미설치·부적합시 사업중지를 명할 수 있다":"시·도지사는 비산먼지 억제시설을 설치하지 않았거나 부적합하면 사업중지를 명할 수 있습니다.","시료 10L 채취시 페놀류 농도 1~20V/Vppm 범위 분석에 적합하다":"시료 10L를 채취할 때 페놀류 농도 1~20V/Vppm 범위를 분석하기에 알맞아요.","시료도입부·분리관·검출기배관으로 스테인리스강 등을 쓴다":"분리관유로는 시료도입부, 분리관, 검출기배관으로 이루어지며 스테인리스강 등을 씁니다.","시료를 과산화수소수에 흡수시켜 황산으로 만든 후 NaOH 용액으로 적정한다":"과산화수소수에 잡아 황산을 만들고, 그 황산을 NaOH 용액으로 적정해 양을 구합니다.","시료성분 기체를 봉입하는 것이 아니라 비흡수가스를 넣는다":"비교셀에는 시료성분 기체가 아니라 적외선을 흡수하지 않는 가스를 넣어요.","시료원자화장치 버너는 전분무버너·예혼합버너가 있다":"원자흡광의 시료원자화장치 버너에는 전분무버너와 예혼합버너가 있어요.","시료채취가 쉽고 준비시간이 짧은 것이 아니라 단수 설계가 까다롭고 준비에 시간이 걸린다":"시료 채취와 준비가 쉬운 방법이 아니며, 단 설계가 까다롭고 준비에 시간이 듭니다.","시료채취관을 굴뚝에 수평하게 하는 것은 아니며, 염소표준착색액으로 요오드산칼륨을 쓰지 않는다":"굴뚝에 채취관을 눕혀 꽂지 않으며, 표준착색액에 요오드산칼륨을 쓰지 않습니다.","시료채취기록지와 함께 보관한다":"자가측정에 쓴 여과지는 시료채취기록지와 함께 보관합니다.","시료채취량은 1~5L, 흡인속도 100~250mL/min이다":"흡착관법은 시료채취량이 1~5L이고 흡인속도는 100~250mL/min이에요.","시료채취량이 1~10mL나 5~15mL인 것은 아니다":"시료를 1~10mL나 5~15mL 뽑는 것은 아닙니다.","시료채취량·흡인속도는 10~20L, 1L/min이다":"용량법에서 시료채취량은 10~20L, 흡인속도는 1L/min입니다.","시료채취 유량은 규정범위 내에서 가능한 많이 채취하는 것이 원칙이다":"규정 범위 안에서 가능한 한 많이 뽑는 것이 시료채취 유량의 원칙입니다.","시설 등의 이전명령은 이 조치에 포함되지 않는다":"시설을 다른 곳으로 옮기게 하는 이전명령은 이 조치 목록에 없습니다.","시설 사용중지·사용제한도 명할 수 있는 조치다":"설치된 시설을 못 쓰게 하거나 쓰는 범위를 줄이게 하는 것도 가능한 조치입니다.","시안화수소·황화수소·악취·이황화탄소·염소 등이다":"초과부과금 대상 오염물질에는 시안화수소, 황화수소, 악취, 이황화탄소, 염소 등이 들어갑니다.","시정장애는 부유분진 중 극미세먼지가 빛을 산란·흡수해 일으킨다":"작은 부유분진이 빛을 흩뜨리고 흡수해서 먼 곳이 흐리게 보이는 현상입니다.","식물·재산 피해는 크지만 인체피해는 적은 것이 아니다":"LA형 스모그는 식물과 재산 피해가 크지만 인체피해는 적다는 말은 맞지 않아요.","식물 피해정도는 기공 개폐·증산작용 정도에 따라 달라진다":"식물이 입는 오존 피해는 기공이 열리고 증산이 일어나는 정도에 비례해 달라집니다.","신규교육은 임명일로부터 1년 이내 1회, 보수교육은 3년마다 1회 받는다":"임명되고 1년 안에 신규교육을 1번 받고, 이후 3년마다 보수교육을 받습니다.","신규교육을 30일 이내에 받아야 하는 것은 아니며, 교육기간이 7일 정도인 것도 아니다":"신규교육 시한은 30일이 아니며, 교육 기간도 7일 정도가 아닙니다.","실리콘고무 격막이 있는 시료기화실이며 분리관 내경은 2~7mm다":"시료기화실에는 실리콘고무 격막이 있고, 분리관 안지름은 2~7mm 정도입니다.","실험일지·검량선 기록지·검사결과 발송대장·정도관리 수행기록철":"악취검사기관은 실험일지, 검량선 기록지, 검사결과 발송대장, 정도관리 수행기록철을 작성합니다.","심한 기온역전 하에서는 MMD가 0에 가까워질 수 있다":"심한 기온역전 상태에서는 최대혼합고가 0에 가까워질 수 있습니다.","아르세나조Ⅲ법은 수산화나트륨용액으로 적정하지 않으며, 가열부 배관에 보통고무관을 쓰지 않는다":"수산화나트륨으로 적정하지 않고, 가열되는 배관에도 보통고무관을 쓰지 않습니다.","아세트산납으로 제거하며 정량범위는 2~10㎍다":"황화수소의 영향은 아세트산납으로 없애고 정량범위는 2~10㎍입니다.","아연아민착염용액을 흡수액으로 쓴다":"황화수소는 아연아민착염용액을 흡수액으로 사용합니다.","아크로레인은 호흡기 자극성, 황화수소는 썩은 달걀냄새의 부식성 물질이다":"아크로레인은 숨길을 자극하는 물질이고, 황화수소는 썩은 달걀 냄새를 내며 부식을 일으킵니다.","아황산가스는 비분산적외선분석법·화학발광법이 아니다":"아황산가스는 비분산적외선분석법이나 화학발광법으로 재지 않습니다.","악취물질은 짧은 시간에 채취하고 입자상 금속·발암성물질은 별도 기준을 적용한다":"악취는 짧게 뽑고, 입자상 금속과 발암성 물질은 다른 기준을 적용합니다.","악취물질을 불완전 연소로 태우면 냄새 강도가 줄지 않는다":"악취 물질이 덜 타면 냄새가 사라지지 않아 처리가 되지 않습니다.","악취배출시설 폐쇄, 사업장 명칭 변경, 시설 임대":"악취배출시설 변경신고 사유는 시설 폐쇄, 사업장 명칭 변경, 시설 임대예요.","악취·비산먼지는 자가측정 대상 오염물질이 아니다":"악취와 비산먼지는 자가측정 대상에서 빠집니다.","안정도는 A~F 6단계로 A가 가장 불안정, F가 가장 안정하다":"A에서 F까지 6단계로 나누며, A가 가장 불안정하고 F가 가장 안정합니다.","안지름은 유량·강도·청소 용이성을 고려해 정한다":"채취관 안지름은 유량, 강도, 청소하기 쉬운 정도를 고려해 정해요.","알데히드·저급유기산·페놀 등 친수성 성분을 제거할 수 있다":"수세법은 알데히드, 저급유기산, 페놀 같은 친수성 성분을 제거할 수 있어요.","알루미나 담체에 CuO를 함침시켜 SO2는 흡착, NOx는 선택적 촉매환원으로 제거한다":"CuO를 입힌 알루미나가 SO2는 붙잡고, NOx는 선택적 촉매환원으로 없앱니다.","알코올만 쓰는 차는 탄화수소 기준만 적용하는 것이 아니다":"알코올만 쓰는 차량에도 탄화수소 말고 다른 항목의 기준이 함께 적용됩니다.","암모니아는 붕산용액에 흡수시킨 후 N/10 황산으로 적정해 정량한다":"붕산용액에 암모니아를 잡은 다음 N/10 황산으로 적정해 양을 구합니다.","암모니아는 이온전극법이 아니며, 불화수소는 자외선흡수법이 아니다":"암모니아는 이온전극법이 아니고, 불화수소도 자외선흡수법으로 재지 않습니다.","암모니아보다 수용성이 약해 상기도보다 깊은 호흡기에 영향을 준다":"염소는 암모니아보다 물에 덜 녹아서 상기도보다 깊은 호흡기에까지 영향을 줍니다.","암모니아수·질산칼륨표준액·과산화수소수를 쓰며 이소프로필알코올은 아니다":"페놀디술폰산법 시약은 암모니아수, 질산칼륨표준액, 과산화수소수이고 이소프로필알코올은 쓰지 않습니다.","암모니아·황화수소처럼 용해도 높은 가스에 적합하다":"액분산형은 암모니아와 황화수소처럼 물에 잘 녹는 가스를 처리하는 데 알맞습니다.","압력손실은 유속의 제곱, 관 길이, 가스밀도에 비례한다":"유속을 제곱한 값과 관의 길이, 가스 밀도가 클수록 압력손실이 큽니다.","압력손실이 밀도에 반비례하거나 관 내경에 비례하는 것은 아니다":"압력손실은 밀도에 비례하고 관 내경에는 반비례하는 관계입니다.","압축비를 높이고 급기온도를 높이며 착화지연기간 분사량을 줄여 억제한다":"디젤 노킹은 압축비와 급기온도를 높이고 착화지연기간의 분사량을 줄여 억제합니다.","액가스비가 가장 크고 동력비가 많이 든다":"제트스크러버는 액가스비가 가장 크고 동력비가 많이 들어요.","액상침강법·관성충돌법·광산란법":"입경을 간접으로 재는 방법에는 액상침강법, 관성충돌법, 광산란법이 있어요.","액적 충돌·액막과 기포 접촉으로 입자를 포집하며 확산되면 접촉이 증가한다":"세정식집진장치는 액적 충돌, 액막과 기포 접촉으로 입자를 잡고, 확산되면 접촉이 늘어요.","액체방울·입자의 주 접촉메커니즘은 충돌이며 압력손실·동력비가 크다":"액체방울에 입자가 부딪혀 잡히는 방식이라서 압력손실과 동력비가 큽니다.","액체연료는 기체연료보다 적은 과잉공기로 완전연소되는 것이 아니라 더 많이 필요하다":"액체연료는 기체연료와 달리 공기를 더 많이 주어야 완전히 탑니다.","액화석유가스(LPG)는 천연가스에서 회수되는 것이 아니며, LNG 주성분이 부탄·프로판인 것도 아니다":"LPG는 천연가스에서 얻지 않으며, LNG의 주성분도 부탄이나 프로판이 아닙니다.","약 2cal/cm²·min로 대기권 밖 태양광 수직면 기준이다":"태양상수는 대기권 밖에서 태양광을 수직면으로 받을 때의 값으로 약 2cal/cm²·min예요.","약 350ppm, 체류시간은 2~4년이며 온난화 기여도가 가장 크다":"대기 중 CO2의 자연농도는 약 350ppm이고 체류시간은 2~4년이며 온난화 기여도가 가장 큽니다.","여객터미널은 1100·1500㎡가 아니라 다른 기준이 적용된다":"공항시설의 여객터미널은 1100㎡나 1500㎡가 아니라 다른 기준을 적용해요.","여과재가 다양해 설계 융통성이 있고 세정집진장치보다 압력손실·동력소모가 적다":"여과재를 고를 폭이 넓어 설계가 자유롭고, 세정식보다 압력손실과 동력이 덜 듭니다.","여과재 교환으로 유지비가 고가이며 원통형을 주로 사용한다":"여과재를 바꿔야 해서 유지비가 비싸며, 모양은 주로 원통형을 사용해요.","여과지홀더 팩킹은 불소수지, 포집 여과지 구멍크기는 1~3㎛인 니트로셀룰로즈 등을 쓴다":"홀더 패킹은 불소수지, 여과지는 구멍이 1~3㎛로 작은 니트로셀룰로즈 같은 재질을 씁니다.","여름에 감소, 겨울에 증가하며 북반구가 남반구보다 높다":"북반구가 더 높고, 식물이 자라는 여름에는 줄었다가 겨울에 다시 늘어납니다.","여행자가 재반출 조건으로 일시 반입하는 자동차도 인증 면제 대상이다":"여행자가 다시 내보내는 조건으로 일시 반입하는 자동차도 인증 면제 대상이에요.","역동식은 교반·연소조건이 좋지만 마모가 많고, 병렬요동식은 이송력이 강하다":"역동식은 쓰레기가 잘 뒤섞이지만 닳기 쉽고, 병렬요동식은 이동시키는 힘이 큽니다.","연1회, 다음해 1월15일까지 보고한다":"비산먼지발생사업 신고현황은 연 1회, 다음해 1월 15일까지 보고합니다.","연간 12톤은 3종 사업장, 2톤 이상 10톤 미만은 4종 사업장이다":"연간 12톤이면 3종이고, 2톤 이상 10톤 미만이면 4종 사업장으로 분류됩니다.","연간 8톤·22톤은 3종 사업장 기준에 해당하지 않는다":"연간 8톤이나 22톤은 3종 사업장 기준에 맞지 않아요.","연기 흐름에 직각 위치에서 태양광선을 측면으로 받으며 관측한다":"연기가 흘러가는 방향과 직각이 되는 자리에서 햇빛을 옆으로 받으며 봅니다.","연료과잉으로 불완전연소가 발생하며 공기비 m=1/Φ다":"등가비가 1보다 크면 연료과잉으로 불완전연소가 생기고, 공기비 m은 1을 Φ로 나눈 값이에요.","연료 질소함량이 낮을수록 변환율이 증가하는 경향이 있다":"Fuel NO는 연료의 질소함량이 낮을수록 변환율이 높아지는 경향이 있습니다.","연면적 3000㎡ 건축물 축조공사, 공사면적 3000㎡ 토목공사":"연면적이 3000㎡인 건축물 공사와 공사면적 3000㎡인 토목공사가 대상입니다.","연소보조장치·이온교환시설·응집시설은 대기오염 방지시설이 아니다":"연소보조장치, 이온교환시설, 응집시설은 방지시설 범위에 들지 않습니다.","연소시 1차로 90% 이상이 NO로 발생하며 NO2 독성은 NO보다 약 5배 크다":"연소할 때 1차로 90% 이상이 NO로 나오고, NO2의 독성은 NO보다 약 5배 큽니다.","연소시 발생하는 유리탄소 중심의 미세 입자상물질이다":"매연은 연소할 때 생기는 유리탄소가 중심인 미세한 입자상물질입니다.","연소온도 감소, 배기열손실 증대, SOx·NOx로 부식이 촉진된다":"공기비가 크면 연소온도가 내려가고 배기열손실이 커지며 SOx와 NOx 때문에 부식이 빨라집니다.","연소온도는 비활성 층물질 용융온도보다 낮아야 하며 과잉공기 50~80%가 든다":"반응 온도가 층물질의 녹는점을 넘지 않아야 하고, 공기는 50~80% 더 넣어야 합니다.","연소용 공기 과잉공급을 약 10% 이내로 줄이면 NOx 생성을 억제할 수 있다":"황산과 과산화수소수에 가스를 잡아 질산이온으로 바꾼 뒤 페놀디술폰산과 반응시켜 색을 냅니다.","연속기록장치가 없으면 10분 간격으로 측정한다":"풍향풍속을 자동 기록하는 장치가 없으면 10분마다 직접 재야 합니다.","열부상에 의한 대류혼합층 높이로 낮에 크고 밤에 작다":"최대혼합고는 열부상에 의한 대류혼합층의 높이이며 낮에 크고 밤에 작아요.","열분해법은 산소가 적은 환원성 분위기에서 탈염소화로 분해하며, 광분해는 250~340nm 자외선이 효과적이다":"열분해는 산소가 적은 환원 분위기에서 염소를 떼어 내고, 광분해는 250~340nm 자외선이 효과적입니다.","열·불활성가스로 흡착제에서 VOC를 탈착시켜 GC로 분석하는 방법이다":"열탈착은 열과 불활성가스로 흡착제에서 VOC를 떼어내 GC로 분석하는 방법입니다.","열섬현상은 고기압·맑고 바람 약한 조건에서 잘 생기며 전원풍이 분다":"맑고 바람이 약한 고기압 날씨에 잘 생기며, 교외에서 도심으로 전원풍이 붑니다.","열섬효과로 도시 중심부가 고온이 되어 상승기류가 생긴다":"도심 기온이 높아지면 공기가 데워져 위로 오르는 흐름이 생깁니다.","열소각법보다 반응시간이 짧고 thermal NOx 생성량이 적다":"촉매소각은 열소각법보다 반응시간이 짧고 thermal NOx가 적게 생깁니다.","열용량이 적고 열전도율이 높은 것이 아니라 그 반대다":"도시 땅바닥은 열을 많이 저장하고 전도율이 낮아서 교외와 반대 특성을 보입니다.","염소를 직접 사용하는 시설의 염소 배출허용기준은 10ppm 이하다":"염소를 직접 쓰는 시설은 염소를 10ppm 이하로 배출해야 합니다.","염소의 흡수액은 과산화수소수가 아니며, 벤젠은 NaOH 흡수대상이 아니다":"염소는 과산화수소수가 아닌 다른 흡수액을 쓰고, 벤젠은 NaOH에 잡히지 않습니다.","염화수소·비소·시안화수소·페놀은 수산화나트륨 용액을 흡수액으로 쓴다":"염화수소, 비소, 시안화수소, 페놀 가스는 수산화나트륨 용액에 잡아 둡니다.","염화인은 알칼리성 용액 흡수탑으로, 크롬산미스트는 수세법으로 제거한다":"염화인은 알칼리 용액에 흡수시키고, 크롬산미스트는 물로 씻어 내서 없앱니다.","옆차붙이 포함, 50cc 미만은 모페드형에 한한다":"이륜자동차는 옆차붙이를 포함하고, 50cc 미만은 모페드형에 한합니다.","예혼합연소로 공기연료비가 거의 일정하다":"가솔린기관은 예혼합연소를 하므로 공기연료비가 거의 일정합니다.","오르자트분석법을 쓰며 담벨형 자기력분석계가 자기식 대표 방식이다":"오르자트분석법은 화학분석법이고, 담벨형 자기력분석계가 자기식의 대표 방식입니다.","오염물은 지면 한 지점에서 배출되거나 0차반응으로 분해되는 것이 아니라 1차반응이다":"오염물질은 1차반응으로 줄어들며, 한 점에서 나오거나 0차반응으로 사라지는 것이 아닙니다.","오염물질 농도가 1ppm 미만으로 보증된 표준가스다":"제로가스는 오염물질 농도가 1ppm 미만으로 보증된 표준가스를 말해요.","오염물질 발생속도를 이겨내고 후드로 흡인하는 데 필요한 최소 기류속도다":"제어속도는 오염물질 발생속도를 이겨 후드로 빨아들이는 데 필요한 최소 기류속도입니다.","오염물질방출 건축자재 사용금지 위반시 1천만원 이하 과태료를 부과한다":"오염물질을 방출하는 건축자재의 사용금지를 어기면 1천만원 이하 과태료를 부과해요.","오염물질 처리방식은 개선계획서 포함사항이 아니다":"처리방식은 조치명령에 따라 내는 계획서의 필수 항목이 아닙니다.","오존은 반응성이 커 축적되지 않으며, 배경농도는 0.1~0.2ppm이 아니다":"오존은 반응이 빨라 쌓이지 않고, 평소 농도도 0.1~0.2ppm이라고 하면 틀립니다.","오존이 자외선을 흡수해 온도를 올린다":"성층권에서는 오존이 자외선을 흡수해 온도를 올립니다.","오존 존재하 질소산화물을 물에 흡수시켜 질산이온으로 만든다":"아연환원법은 오존이 있는 상태에서 질소산화물을 물에 흡수시켜 질산이온으로 만듭니다.","오존층은 지상 50~60km 구간이 아니라 그보다 낮은 고도에 위치한다":"오존층은 50~60km보다 낮은 고도에 자리 잡고 있습니다.","오존층 파괴물질(CFC) 생산·사용 규제 협약이다":"몬트리올의정서는 오존층 파괴물질(CFC)의 생산과 사용을 규제하는 협약입니다.","오존층 파괴물질은 자유라디칼을 생성해 오존층을 파괴한다":"오존층 파괴물질은 자유라디칼을 만들어 오존층을 파괴해요.","오존층 파괴의 원인이 되는 활성 큰 기체가 아니라 비교적 안정한 기체다":"아산화질소는 오존층을 파괴하는 활성 기체가 아니라 비교적 안정한 기체입니다.","옥내 태양열 자연건조시설은 배출시설이 아니며, 100KW 발전내연기관은 기준 대상이 아니다":"실내에서 햇볕으로 말리는 시설은 배출시설이 아니고, 100KW 발전기관도 해당하지 않습니다.","온도가 높을수록, 용해도가 적을수록 커진다":"온도가 높거나 용해도가 작은 기체일수록 헨리상수가 커집니다.","온도와 가연성물질 농도에 의존하며 Arrhenius식을 따른다":"연소가 빨리 일어나는 정도는 온도와 가연물 농도에 따르고 Arrhenius식으로 나타냅니다.","온실가스로도 작용하며 태양빛·NOx·VOC 반응으로 생긴다":"대류권 오존은 햇빛과 NOx, VOC가 반응해 만들어지고 온실가스 역할도 합니다.","온실효과 기여도는 CO2가 CH4보다 크다":"온실효과에 더 크게 기여하는 쪽은 CH4가 아니라 CO2입니다.","온위가 높아도 공기밀도가 커지지 않으며, 습윤단열감률과 같을 때 일정한 것도 아니다":"온위가 높다고 공기가 무거워지지 않으며, 습윤단열감률일 때 일정한 것도 아닙니다.","올레핀탄화수소 측정법은 환경대기 탄화수소 시험방법이 아니다":"올레핀탄화수소를 재는 방법은 환경대기 탄화수소 시험법에 없습니다.","와류유속계 사용시 압력계·온도계는 유량계 상류측이 아니라 다른 위치에 설치한다":"와류유속계를 쓸 때 압력계와 온도계는 유량계 상류 말고 다른 곳에 설치합니다.","완전연소로 연료·산화제 혼합이 이상적이다":"연료와 산화제가 딱 맞는 비율로 섞여 남김없이 타는 이상적인 상태입니다.","요오드 적정법으로 정량하며 종말점 지시약은 녹말(전분)용액이다":"요오드로 적정해서 양을 구하고, 끝점은 녹말 용액이 색으로 알려 줍니다.","용리액조·송액펌프·시료주입장치·분리관·써프렛서·검출기·기록계":"이온크로마토그래피는 용리액조, 송액펌프, 시료주입장치, 분리관, 써프렛서, 검출기, 기록계로 이루어집니다.","용매와 화학적 성질이 비슷해야 하며 용해도 작은 기체에는 헨리법칙이 성립한다":"흡수액은 용매와 성질이 비슷해야 잘 녹고, 용해도가 작은 기체는 헨리법칙을 따릅니다.","용액전도율법·불꽃광도법으로 측정한다":"아황산가스는 용액전도율법과 불꽃광도법으로 연속 측정합니다.","용액전도율법은 NOx 자동측정법이 아니며, 검출기는 비분산 자외선광배전관이 아니다":"NOx 자동측정에 용액전도율법은 쓰이지 않고, 검출기도 비분산 자외선광배전관이 아닙니다.","용해도가 비교적 작은 기체에 적용되며 압력은 액중농도에 비례한다":"헨리의 법칙은 용해도가 비교적 작은 기체에 적용되며, 압력이 액중농도에 비례한다는 내용입니다.","용해도가 크고 휘발성·점성·부식성은 낮아야 한다":"흡수액은 용해도가 크고 휘발성, 점성, 부식성은 낮아야 해요.","운영상황을 사실대로 기록하지 않으면 300만원 이하 과태료를 부과한다":"운영 상황을 거짓으로 적거나 빠뜨리면 300만원 이하의 과태료를 문니다.","원료탄 건류로 얻는 2차연료로 발열량은 약 8000kcal/kg, 주성분은 탄소다":"원료탄을 구워 얻는 2차 연료로, 발열량 약 8000kcal/kg에 대부분이 탄소입니다.","원심력÷중력이며, 입구유속이 빠를수록 효율·압력손실이 커진다":"원심력을 중력으로 나눈 값이 분리계수이며, 입구 유속이 빠르면 효율과 압력손실이 함께 오릅니다.","원인물질 외의 물질과 반응해 유발되는 것이 아니라 두 가지 이상 악취물질의 공동작용으로 생긴다":"상승악취는 원인물질 외의 물질과 반응해 생기는 것이 아니라 둘 이상의 악취물질이 함께 작용해 생깁니다.","원자가 빛을 흡수했다가 원상태로 돌아갈 때 방사하는 스펙트럼선이다":"공명선은 원자가 빛을 흡수했다가 원래 상태로 돌아가며 내놓는 스펙트럼선이에요.","원자흡광 장치구성에 포함되지 않는다":"분리관은 원자흡광 장치의 구성에 포함되지 않습니다.","원추형은 역전층이 해소되는 과정(훈증형)과는 무관하다":"훈증형은 역전층이 사라지는 과정에서 나타나지만, 원추형은 이 과정과 관계가 없어요.","원통부·원추하부의 반경은 클수록이 아니라 작을수록 집진율·분리계수가 커진다":"원통부와 원추하부 반경은 작을수록 집진율과 분리계수가 커지며, 클수록 커지는 것이 아닙니다.","월평균검사대수 360대 미만이면 과징금 720만원, 1800대 초과시 100대마다 200만원 추가한다":"월평균 검사대수가 360대 미만이면 720만원이고, 1800대를 넘으면 100대마다 200만원이 늘어납니다.","월평균검사대수는 최근 3개월이 아니라 6개월 평균이며, 72만원·360만원은 아니다":"월평균 검사대수는 3개월이 아닌 6개월 평균이고, 72만원이나 360만원은 금액이 다릅니다.","유기용매에 잘 녹지만 무수불화수소는 약산성이 아니다":"불화수소는 유기용매에 잘 녹으며, 무수불화수소는 약산성이 아닙니다.","유기용제 회수용은 2개 이상으로 구성해 번갈아 운전한다":"유기용제를 회수하는 흡착탑은 2개 이상 두고 교대로 돌려 끊김 없이 씁니다.","유기할로겐·니트로화합물·유기금속화합물 등 전자친화력 큰 성분에 적합하다":"ECD는 유기할로겐, 니트로화합물, 유기금속화합물처럼 전자친화력이 큰 성분에 알맞아요.","유독물질을 포위 가능하면 쓰며 플랜지로 효율을 높인다":"유독물질을 에워쌀 수 있으면 포위식을 쓰고, 플랜지를 달면 흡인 효율이 올라갑니다.","유리관·석영관·염화비닐관·불소수지관을 쓴다":"오르토톨리딘법의 시료채취관은 유리관, 석영관, 염화비닐관, 불소수지관을 씁니다.","유전가스 중 건성가스는 대부분 메탄이 주성분이다":"유전에서 나오는 건성가스는 메탄이 대부분인 가스입니다.","이 기관들이 개선명령 이행 확인을 위한 오염도검사를 수행한다":"이 기관들이 개선명령을 이행했는지 확인하려고 오염도검사를 합니다.","이들 서류는 3년간 보존해야 한다":"이 서류들은 3년간 보존해야 해요.","이들은 물을 가압 공급해 함진가스를 세정하는 방식이다":"이 스크러버들은 물을 가압해 공급하면서 함진가스를 씻는 방식이에요.","이들은 연료 성능을 향상시키는 용도로 인정받는다":"이 첨가제들은 연료의 성능을 높이는 용도로 인정받습니다.","이들은 지구온난화 등으로 생태계 변화를 가져올 수 있는 물질이다":"이 물질들은 지구온난화 등을 일으켜 생태계 변화를 가져올 수 있습니다.","이 방법은 질소산화물의 주시험법이며, 페놀·브롬화합물의 주시험법은 아니다":"질소산화물의 주시험법이 이 방법이며, 페놀과 브롬화합물은 다른 주시험법을 씁니다.","이 방법이 벤조(a)피렌의 공정시험 주시험법이다":"벤조(a)피렌을 공정시험으로 재는 주된 방법이 이것입니다.","이산화질소·과염소산은 온실가스가 아니다":"이산화질소와 과염소산은 온실가스 목록에 들지 않습니다.","이산화탄소·메탄·수소불화탄소·육불화황":"온실가스는 이산화탄소, 메탄, 수소불화탄소, 육불화황이에요.","이산화황·염화수소·벤젠은 지정악취물질이 아니다":"이산화황, 염화수소, 벤젠은 악취방지법이 지정한 악취물질이 아닙니다.","이 세 가지 위반은 1차부터 바로 조업정지 처분을 받는다":"이 세 위반은 경고 단계를 거치지 않고 1차부터 조업을 멈추게 합니다.","이소프로필알코올·초산을 가해 침전적정하며 50~700ppm에 적용한다":"아르세나조Ⅲ법은 이소프로필알코올과 초산을 넣고 침전적정하며 50~700ppm에 적용해요.","이온크로마토그래프법·흡광광도법은 CO 분석법이 아니다":"CO는 이온크로마토그래프나 흡광광도 방식으로 재는 항목이 아닙니다.","이온크로마토그래피법·비분산적외선분석법은 벤조(a)피렌 측정법이 아니다":"이온크로마토그래피법과 비분산적외선분석법으로는 벤조(a)피렌을 재지 않습니다.","인화점은 불씨로 연소가 시작되는 최저온도, 발화점은 점화 없이 자연발화하는 온도다":"인화점은 불씨로 연소가 시작되는 최저온도이고, 발화점은 불씨 없이 저절로 타는 온도예요.","일사량 많은 여름철에 자동차 배출가스가 주원인으로 발생했다":"LA형 스모그는 일사량이 많은 여름철에 자동차 배출가스가 주원인으로 생겼습니다.","일산화탄소·석면은 초과부과금 부과대상 오염물질이 아니다":"일산화탄소와 석면은 초과부과금을 부과하는 오염물질에 해당하지 않아요.","일산화탄소·이산화질소는 기후·생태계변화 유발물질이 아니다":"일산화탄소와 이산화질소는 기후와 생태계를 바꾸는 지정 물질에 들지 않습니다.","임펄스 스크러버(Impulse Scrubber)는 가압수식 스크러버가 아니다":"임펄스 스크러버는 가압수식 계열이 아닌 별개의 세정장치입니다.","입경간격별 개수·질량 비율로 나타내는 방법이다":"빈도분포는 입경 간격별 개수나 질량의 비율로 나타내는 방법입니다.","입경·밀도가 클수록, 선회속도가 클수록 분리속도·집진율이 커진다":"사이클론은 입자 지름과 밀도가 크고 선회속도가 빠를수록 분리속도와 집진율이 올라갑니다.","입경을 간접적으로 측정하며 입자의 질량크기분포를 알 수 있다":"관성충돌법은 입경을 간접으로 재며 입자의 질량크기분포를 알 수 있어요.","입구유속은 보통 7~15m/s이며 가동부가 없다":"접선유입식 사이클론은 입구유속이 보통 7~15m/s이고 움직이는 부품이 없습니다.","입자가 미세할수록 부착성이 커지고 비표면적이 크면 장치벽면을 폐색시킨다":"입자가 미세하면 서로 잘 붙고, 비표면적이 크면 장치 벽에 달라붙어 막힙니다.","입자가 파장과 비슷하거나 큰 경우 생기며 레일리산란 조건과는 다르다":"빛의 파장과 입자 크기가 비슷하거나 입자가 더 크면 생기는 산란입니다.","입자가 파장보다 매우 작을 때 생기며 세기는 파장의 4제곱에 반비례한다":"입자가 파장보다 훨씬 작으면 일어나며, 산란 세기가 파장의 4제곱에 반비례합니다.","입자상·가스상·가시도 문제에 응용되며 다변량·인자·공간계열 분석법을 쓴다":"수용모델은 입자상, 가스상, 가시도 문제에 응용되며 다변량, 인자, 공간계열 분석법을 씁니다.","입자 응집이 낮아지는 것이 아니라 촉진된다":"증습은 입자를 서로 뭉치게 해서 먼지를 더 잘 포집하게 합니다.","자가측정 기록은 1년이 아니라 최종기재일로부터 6개월간 보존한다":"기록은 최종 기재일을 기준으로 6개월 동안 두면 됩니다.","자극성이 경미하지만 수중에서 염산으로 분해돼 급성증상이 늦게 나타난다":"포스겐은 처음엔 자극이 약하지만 물에서 염산이 되어 증상이 뒤늦게 나옵니다.","자기식과 전기화학식(전극방식)이 있다":"산소 자동측정에는 자기식과 전기화학식(전극방식)이 있어요.","자기식 원리를 적용한 것이 아니라 전기화학적 원리를 쓴다":"전극방식은 자기식 원리가 아니라 전기화학적 원리를 이용해요.","자기착화온도를 높이고 화염속도를 키우며 말단가스 온도·압력을 낮춰 방지한다":"가솔린 노킹은 자기착화온도를 높이고 화염속도를 키우며 말단가스의 온도와 압력을 낮춰 막습니다.","자동차 개발·전시 목적의 연구기관용 차량은 생략 대상이 아니다":"연구기관이 개발이나 전시용으로 쓰는 차량은 인증 생략 대상이 아닙니다.","자동차 소유자 성명은 기재사항이 아니며, 바탕색이 흰색·초록색인 것도 아니다":"소유자 이름은 적지 않으며, 바탕색도 흰색이나 초록색이 아닙니다.","자동차 질소산화물이 아니라 SOx·복사역전이 원인이다":"런던스모그의 원인은 자동차 질소산화물이 아니라 SOx와 복사역전입니다.","자연적 NOx 배출량은 인위적 배출량의 7~15배로 더 많다":"자연에서 나오는 NOx가 사람이 만든 NOx보다 7~15배 많습니다.","자연통풍은 굴뚝 자체에 의한 통풍이며 흡인통풍시 로내는 부압이 된다":"자연통풍은 굴뚝 높이로 생기는 흡인력이고, 흡인통풍은 로 안을 대기압보다 낮게 만듭니다.","자외선형광법(또는 자외선광도법)으로 측정한다":"아황산가스는 자외선형광법(또는 자외선광도법)으로 측정해요.","자외선흡수법·적외선흡수법·화학발광법을 쓴다":"NOx 자동측정법에는 자외선흡수법, 적외선흡수법, 화학발광법이 있어요.","자유대기(고도 1km 이상)에서 등압선이 직선일 때 등압선과 평행하게 분다":"지균풍은 고도 1km 이상 자유대기에서 등압선이 직선일 때 등압선과 나란히 불어요.","자유대기층에서 기압경도력과 전향력만으로 등압선과 평행하게 분다":"지균풍은 자유대기층에서 기압경도력과 전향력만으로 등압선과 나란히 붑니다.","자일렌 권고기준은 600㎍/m3이 아니며, HCHO 유지기준도 120㎍/m3이 아니다":"자일렌의 권고기준과 포름알데히드 유지기준은 각각 이 문장에 적힌 수치와 다릅니다.","작은 전기저항으로 인한 재비산을 방지하고 집진면이 청결해 높은 전계강도를 얻는다":"습식 전기집진은 전기저항이 작아 재비산이 없고 집진면이 깨끗해 높은 전계강도를 얻어요.","작을수록 작은 입경의 더스트도 제거할 수 있다":"배기관 지름이 작을수록 입경이 작은 더스트까지 제거할 수 있어요.","장애물 높이의 2배 이상 거리를 두거나 각도 조건을 만족해야 한다":"장애물 높이의 2배 이상 떨어지거나 각도 조건을 맞추어야 합니다.","저비저항은 암모니아가스 주입으로, 고비저항은 수분·SO2 등 전해질 주입으로 조절한다":"저비저항은 암모니아가스를 넣어, 고비저항은 수분이나 SO2 같은 전해질을 넣어 조절해요.","저온농축관에 농축 후 가열하는 방식이며, 머무름부피는 운반가스 부피로 측정한다":"저온농축관에 모은 뒤 가열해 떼어 내는 두 단계 방식이며, 머무름부피는 운반가스 양으로 잽니다.","저장·계량·운반이 용이하지만 연소온도가 높아 국부가열 위험이 있다":"액체연료는 저장, 계량, 운반이 쉽지만 연소온도가 높아 국부가열의 위험이 있습니다.","저장시설 및 주유시설은 VOC배출시설 신고대상이다":"저유소와 주유소의 저장시설 및 주유시설은 VOC배출시설 신고대상이에요.","적갈색 자극성 기체로 NO보다 5~7배 독성이 강하다":"적갈색 기체로 NO보다 5~7배 독하고 숨길을 자극합니다.","적갈색 자극성 기체로 NO보다 독성이 강하고 헤모글로빈 결합력이 CO의 약 300배다":"헤모글로빈과 잘 붙는 정도가 CO의 약 300배이며, 자극성 적갈색 기체입니다.","적도 오존층은 극지방보다 얇으며, HCFCs도 오존층 파괴력이 없지 않다":"적도 쪽 오존층이 극지방 쪽보다 얇고, HCFCs도 오존층을 파괴하는 힘이 있습니다.","적외선분석법·적외선형광법은 SO2 측정법이 아니다":"적외선분석법과 적외선형광법은 SO2 측정법에 속하지 않습니다.","적외선을 흡수하지 않는 가스를 대조용으로 쓴다":"NDIR의 비교가스는 적외선을 흡수하지 않는 가스로, 시료와 비교하는 기준으로 씁니다.","적은 과잉공기로도 완전연소가 가능하고 매연이 거의 없다":"기체연료는 과잉공기를 적게 써도 완전연소가 되어 매연이 거의 생기지 않습니다.","적은 과잉공기로 완전연소가 가능한 것은 액체연료가 아니라 기체연료다":"공기를 조금만 더 넣어도 다 타는 연료는 액체가 아니라 기체연료 쪽입니다.","전기만 동력으로 쓰는 차는 1회 충전 주행거리로 종이 구분된다":"전기만으로 움직이는 차는 한 번 충전해서 달리는 거리를 보고 종을 가릅니다.","전기저항이 10^11Ω·cm 이상이어도 점핑현상이 아니라 역전리가 발생한다":"10^11Ω·cm 이상이면 점핑현상이 아니라 역전리가 일어납니다.","전단응력은 속도구배에 반비례가 아니라 비례한다":"Hagen 점성법칙에서 전단응력은 속도구배에 반비례하지 않고 비례합니다.","전향력은 적도에서 0이고 극지방에서 최대이며 원심력은 곡률에 비례하는 별개 힘이다":"전향력은 위도가 높아질수록 세져 적도에서는 0이고, 원심력은 곡률에 따라 달라지는 다른 힘입니다.","점검당시 누적주행거리, 주차장소, 자동차등록번호를 기재한다":"운행정지표지에는 점검당시 누적주행거리, 주차장소, 자동차등록번호를 적어요.","점결성은 코크스 생산에 중요하며 강점결탄을 주로 쓴다":"점결성은 코크스를 만들 때 중요해서 주로 강점결탄을 사용합니다.","점도·잔류탄소가 증가하고 유동점도 높아진다":"무거운 중유일수록 끈적이고 탄소 잔류가 늘며 굳는 온도도 오릅니다.","점도·표면장력·비중 등이 미립화 정도에 영향을 준다":"끈적임, 표면장력, 비중에 따라 기름이 얼마나 잘게 쪼개지는지가 달라집니다.","점착성·조해성 분진, 연소성·폭발성 가스 처리가 가능하다":"점착성·조해성 분진과 연소성·폭발성 가스도 세정식으로 처리할 수 있습니다.","접지저항은 10Ω 이하, 전원변동은 지정전압의 10% 이내여야 한다":"접지는 저항이 낮게, 전원은 지정전압 대비 변동폭이 작게 유지되도록 갖춰야 합니다.","정규분포·대수정규분포·Rosin-Rammler식 등으로 나타낸다":"정규분포, 대수정규분포, Rosin-Rammler식 등으로 누적된 입경 분포를 표현합니다.","정상상태(시간에 따른 농도변화 없음), 점원에서 연속방출을 가정한다":"확산방정식은 시간에 따라 농도가 변하지 않는 정상상태이고, 점원에서 연속방출한다고 가정해요.","정상연소속도가 큰 혼합가스일수록 폭굉유도거리는 짧아진다":"정상연소속도가 큰 혼합가스는 폭굉으로 바뀌기까지 거리가 짧습니다.","정압(ΔP)은 회전수 제곱에, 동력(W)은 회전수 세제곱에 비례한다":"정압은 회전수를 제곱한 만큼, 동력은 세제곱한 만큼 커집니다.","정화조절밸브(Purge Control Valve)가 포함된다":"연료증발가스를 막는 장치에는 정화조절밸브(Purge Control Valve)가 들어갑니다.","제로드리프트의 2배에 해당하는 먼지농도다":"영점이 흔들리는 폭(제로드리프트)의 두 배에 해당하는 먼지농도가 검출한계입니다.","제작·판매한 경우 과징금 비율은 5/100가 아니다":"인증 없이 만들어 판 경우의 부과 비율은 5/100와 다른 값입니다.","제작·판매한 경우 과징금은 매출액×3/100×가중부과계수다":"인증 내용과 다르게 제작·판매한 경우 과징금은 매출액에 3/100과 가중부과계수를 곱해요.","제조기준에 맞는 첨가제·촉매제는 용기 앞면 제품명 밑에 표시한다":"제조기준에 맞는 첨가제와 촉매제는 용기 앞면의 제품명 바로 아래에 적습니다.","제조시설·저장시설·출하시설도 신고대상이다":"석유정제의 제조시설, 저장시설, 출하시설도 신고대상입니다.","제트스크러버는 처리가스량이 많을 때 적합한 것이 아니라 불리하다":"제트스크러버는 가스량이 많은 경우에는 오히려 맞지 않습니다.","제품명 글자크기의 100분의 30 이상이어야 한다":"표시 글자 크기는 제품명 글자 크기의 100분의 30 이상이어야 해요.","조작이 복잡하고 비용이 높으며 강한 산화제가 필요하다":"습식배연탈질법은 조작이 복잡하고 비용이 높으며 강한 산화제가 필요해요.","조치명령 받은 자는 개선기간·개선내용및방법·운영관리 진단계획을 제출한다":"조치명령을 받으면 개선기간, 내용과 방법, 운영관리 진단계획을 내야 합니다.","좁은 각도의 짧은 화염이 아니라 비교적 넓은 각도를 낸다":"저압공기식 버너의 화염은 좁고 짧은 것이 아니라 비교적 넓은 각도로 퍼집니다.","주로 NO2가 아니라 NO다":"화염 속에서 생기는 NOx는 주로 NO2가 아니라 NO예요.","주로 전도도검출기를 쓰며 실온 10~25℃·습도 30~85%를 유지한다":"주로 전도도검출기를 쓰며, 온도 10~25℃에 습도 30~85% 환경에서 장비를 운전합니다.","주성분은 CO2·H2가 아니라 CO·N2 중심의 저발열량 가스다":"고로가스의 주성분은 CO2와 H2가 아니라 CO와 N2이고 발열량이 낮아요.","주 이동방향은 X축이며 가우시안모델 시료채취시간은 보통 10분이다":"주 이동방향을 X축으로 잡고, 가우시안모델의 시료채취시간은 보통 10분으로 봅니다.","주풍향이 90° 이상 변하면 보정계수를 적용하며, 채취는 1시간이 아니라 24시간 이상이다":"바람 방향이 90° 넘게 바뀌면 보정계수를 쓰고, 채취는 하루 단위로 해야 합니다.","주행거리 80~160km 미만은 제2종이다":"충전 한 번에 80km 이상 160km 미만을 가면 제2종으로 분류합니다.","중대경보 조치는 자동차 사용제한 명령이 아니다":"중대경보 단계의 조치에는 자동차 사용제한 명령이 포함되지 않아요.","중립 대기, 흐리고 바람 약한 조건에서 생긴다":"원추형 연기는 대기가 중립이고 흐리면서 바람이 약한 날에 굴뚝에서 생깁니다.","중립조건은 환경감률=건조단열감률, 등온조건은 기온감률이 없어 혼합이 잘 안 된다":"환경감률과 건조단열감률이 같으면 중립이고, 등온은 기온이 높이에 따라 변하지 않아 섞이기 어렵습니다.","중유전용 보일러를 개조 없이 그대로 쓸 수 있는 것이 아니다":"중유전용 보일러에 그대로 쓸 수 있는 연료로 보기는 어렵습니다.","중화적정법에서 이산화탄소는 영향이 없는 것이 아니라 방해성분으로 작용한다":"이산화탄소는 중화적정 결과를 흔드는 방해성분입니다.","증기상 PAHs 채취는 XAD-2수지, PUF, Tenax로 한다":"기체 상태로 떠 있는 PAHs는 XAD-2수지, PUF, Tenax에 잡습니다.","증기상이 아니라 입자상 PAHs 채취에 쓰인다":"석영필터는 증기상이 아니라 입자상 PAHs를 채취하는 데 쓰입니다.","증기압·수용성이 낮고 벤젠 등에 녹는 지용성이라 토양에 흡수된다":"물에 안 녹고 증기압도 낮으며 벤젠 등에 녹는 지용성이라 토양에 흡수됩니다.","증기압이 높은 것은 고정상액체 조건에 맞지 않는다":"증기압이 높은 액체는 고정상액체의 조건에 맞지 않아요.","지구자전에 의한 가속도힘으로 바람 방향만 바꾸고 속도에는 영향 없다":"전향력은 지구자전 때문에 생기는 가속도힘으로 바람의 방향만 바꾸고 속도에는 영향을 주지 않아요.","지구표면 단위면적 평균태양에너지 Cm=C×(πR²/4πR²)로 계산한다":"지구표면 단위면적의 평균태양에너지 Cm은 C에 πR²/4πR²를 곱해 계산합니다.","지면 전역에 균등하게 분포하며 방출과 동시에 균등 혼합된다":"상자모델에서 오염원은 지면 전체에 고르게 퍼져 있고 방출되자마자 균등하게 섞입니다.","지방(유역)환경청, 시·도 보건환경연구원, 환경관리공단이다":"개선명령을 따랐는지 오염도를 검사하는 기관은 환경청, 보건환경연구원, 환경관리공단입니다.","지방이 풍부한 피하조직·골수에 고농도로 축적돼 오래 잔존한다":"벤젠은 지방이 풍부한 피하조직과 골수에 고농도로 쌓여 오래 남아요.","지방족 HC 제어에 흡수법은 적절한 기술이 아니다":"지방족 탄화수소를 흡수법으로 제어하는 것은 적절하지 않습니다.","지역배경·광화학오염물질·산성강하물·유해대기물질측정망":"환경부장관이 설치하는 측정망에는 지역배경, 광화학오염물질, 산성강하물, 유해대기물질측정망이 있어요.","지표냉각으로 생기는 것이 아니다":"침강역전은 지표가 식어서 생기는 것이 아니고, 지표냉각으로 생기는 것은 복사역전이에요.","지표에 자외선이 더 많이 도달한다":"오존층이 줄어들면 지표에 도달하는 자외선이 더 많아집니다.","직경 4.5m 초과시 측정점수는 20점이고, 반경 2.5m면 측정점수 20점이다":"굴뚝 직경이 4.5m를 넘으면 측정점수는 20점이고, 반경이 2.5m여도 20점입니다.","직사일광이 없고 진동이 없는 곳에 설치한다":"GC는 직사일광이 없고 진동이 없는 곳에 설치해요.","진동형은 음파·횡·상하진동으로 턴다":"진동형은 음파나 가로, 위아래 진동을 주어 여과포에 붙은 먼지를 털어 냅니다.","질산-과염소산법으로 처리한다":"유기물이 소량 들어 있는 시료는 질산-과염소산법으로 전처리합니다.","질산암모늄 가한 황산이 아니라 아연아민착염에 흡수시켜 발색시킨다":"아연아민착염에 흡수시키고 색을 내며, 질산암모늄을 넣은 황산은 쓰지 않습니다.","질산은 용액은 이 방법의 시약이 아니며, 가스크로마토그래프법도 염화수소 측정법이 아니다":"질산은 용액은 쓰지 않으며, 가스크로마토그래프로는 염화수소를 재지 않습니다.","징수실적·체납처분현황은 매분기 종료 후 15일 이내 보고한다":"배출부과금 징수실적과 체납처분현황은 분기가 끝난 뒤 15일 이내에 보고해요.","징수유예기간 연장이나 분할납부 횟수 증가는 제한 없이 할 수 있는 것이 아니다":"유예기간을 늘리거나 나눠 내는 횟수를 늘리는 일에는 한도가 있습니다.","징수유예기간은 유예일 다음날부터 2년 이내다":"미룬 날 다음 날부터 2년 안에 내면 되는 것이 초과부과금의 유예 기간입니다.","찬곳은 0~4℃가 아니며, 온수·열수는 60~70℃·약100℃ 기준이다":"찬곳은 0~4℃가 아니고, 온수는 60~70℃, 열수는 약 100℃를 기준으로 합니다.","채취관 안지름은 6~25mm, 도관 안지름은 4~25mm로 한다":"채취관은 6~25mm, 도관은 4~25mm 범위의 안지름을 갖습니다.","채취관 재질로 스테인리스강·보통강철은 적합하지 않다":"스테인리스강이나 보통강철은 포름알데히드 채취관 재질로 맞지 않습니다.","채취부 펌프는 개방형이 아니라 배기능력 5L/min 이상의 밀폐형을 쓴다":"개방형이 아닌 밀폐형 펌프를 쓰며, 배기능력이 5L/min 이상이어야 합니다.","채취위치 주변에 배전·급수설비를 배제하는 것이 좋은 것은 아니다":"채취위치 주변에 배전설비와 급수설비를 두지 않는 것이 좋은 것은 아닙니다.","채취자는 2인 이상 1조로 하며 옥외작업시 바람 부는 쪽에서 작업한다":"두 명 이상이 한 조로 채취하고, 야외에서는 바람이 불어오는 쪽에서 작업합니다.","처리가스량이 많을 때는 압력손실이 적어 유리하다":"충전탑은 처리가스량이 많을 때 압력손실이 적어 유리해요.","처리가스량이 많을 때 쓰며 총효율은 단일장치와 같은 80%다":"병렬로 이으면 한 대가 처리하는 만큼의 효율 80%를 유지하면서 더 많은 가스를 처리합니다.","천재지변·경영위기 등으로 납부 곤란시 징수유예·분할납부가 가능하다":"천재지변이나 경영위기로 납부가 어려우면 징수유예나 분할납부를 할 수 있어요.","청정연료 사용과 탈황설비 설치다":"산성비를 줄이려면 청정연료를 쓰고 탈황설비를 설치해요.","초과부과금 부과대상 오염물질에 포함된다":"먼지도 초과부과금을 매기는 오염물질에 속합니다.","초기투자비가 적어 소규모·노후 보일러에 많이 쓰이며 배기가스 온도가 잘 안 떨어진다":"석회석법은 초기투자비가 적어 소규모나 노후 보일러에 많이 쓰이고 배기가스 온도가 잘 떨어지지 않습니다.","촉매 선택성이 있어도 암모니아 산화 등 부반응이 없는 것은 아니다":"선택성이 좋은 촉매라도 암모니아가 따로 산화되는 일은 완전히 막을 수 없습니다.","촉매소각·생물막·UV산화로 제어한다":"지방족 탄화수소 VOC는 촉매소각, 생물막, UV산화로 제어합니다.","총탄화수소분석에 흡광광도법·원자흡광광도법·흡광차분광방식은 쓰지 않는다":"흡광광도법, 원자흡광광도법, 흡광차분광방식은 총탄화수소 분석에 쓰이지 않습니다.","총효율=1-(1-η1)(1-η2)로 높은 처리효율을 얻는다":"직렬연결의 총효율은 1에서 (1-η1)(1-η2)를 뺀 값이라서 높은 처리효율을 얻어요.","총휘발성유기화합물(TVOC) 기준은 2.5 이하다":"휘발성유기화합물을 모두 합친 양의 방출 기준은 2.5 이하입니다.","최고저장높이 1/3 이상 방진벽, 물뿌림 반경 7m 이상 시설을 설치한다":"야적 높이의 1/3 이상 방진벽을 세우고, 물뿌림 반경 7m 이상인 시설을 설치합니다.","최근 1년간 같은 위반 횟수로 가중하며 2분의 1 범위에서 감경한다":"과태료는 최근 1년간 같은 위반을 한 횟수만큼 가중하고, 감경은 2분의 1 범위 안에서 합니다.","최근 조업한 30일간 평균치를 시간으로 산정한다":"일일조업시간은 최근 조업한 30일 동안의 평균치를 시간으로 계산합니다.","최대 2억원이며 환경개선특별회계 세입으로 한다":"과징금은 최대 2억원이며 환경개선특별회계의 세입으로 들어갑니다.","최대눈금치의 약 50%와 90%(스팬가스) 농도를 갖는다":"교정가스는 최대눈금치의 약 50%와 90% 농도를 가지며, 90%가 스팬가스입니다.","최소 0.5도 단위로 기록한다":"비탁도는 최소 0.5도 단위로 기록합니다.","최초 제작시점부터 적발시점까지의 총 매출액으로 산정한다":"배출가스 과징금의 매출액은 최초 제작시점부터 적발시점까지의 총 매출액으로 산정합니다.","출구 가스속도가 작고 방향전환 횟수가 많을수록 집진율이 좋아진다":"출구 가스가 느리고 진행 방향이 자주 바뀔수록 먼지가 더 잘 걸러집니다.","충전물 간격 단면적은 작은 것이 아니라 충분한 접촉을 위해 적절히 커야 한다":"충전물 사이의 단면적은 작아야 하는 것이 아니라 충분히 접촉하도록 알맞게 커야 합니다.","충전제가 없어 압력손실이 작고 구조가 간단하며 설비비·유지비가 적다":"채우는 충전제가 없어서 압력손실이 작고 구조가 단순해 설비비와 유지비가 덜 듭니다.","충전탑 같은 세정장치는 적절한 처리법이 아니다":"충전탑 같은 세정장치는 불소화합물을 처리하는 적절한 방법으로 보기 어렵습니다.","충전탑 높이는 이동단위수×이동단위높이로 계산하며 D/d=8~10이면 편류가 적다":"충전탑 높이는 이동단위수와 이동단위높이를 곱해 구하고, D/d가 8~10이면 편류가 적어요.","측쇄가 C3까지는 옥탄가가 증가하지만 그 이상이면 감소한다":"곁사슬이 C3까지 늘 때는 옥탄가가 오르고, 그보다 길면 오히려 떨어집니다.","측정공에서 측정점까지 삽입해 전압공을 배출가스 흐름방향에 직면시킨다":"피토관은 측정공에서 측정점까지 넣어 전압공이 배출가스 흐름 방향을 정면으로 향하게 합니다.","측정범위는 0.02~0.8㎍/mL가 아니다":"측정범위가 0.02~0.8㎍/mL라고 하면 틀립니다.","측정범위는 0~5~50ppm, 측정주기는 1시간에 4회 이상이다":"비메탄탄화수소법은 측정범위가 0~5~50ppm이고 측정주기는 1시간에 4회 이상입니다.","측정소 1개라도 기준을 초과하면 해당지역에 경보를 발령한다":"측정소 한 곳이라도 기준을 넘으면 그 지역에 경보를 발령합니다.","측정위치를 하부 끝에서 내경의 1/2배로 잡는 것은 아니다":"측정위치를 아래 끝에서 내경의 1/2배 되는 곳에 두는 것은 아닙니다.","측정자료를 입력자료로 쓰므로 시나리오 작성과 미래예측은 어렵다":"측정값을 입력으로 쓰는 모델이라서 앞으로를 예측하는 시나리오를 짜기 어렵습니다.","측정점 배출가스유속 대비 상대오차 -5~+5% 범위로 맞춘다":"흡인유속을 측정점 유속에 맞추되 오차는 -5~+5% 범위로 둡니다.","침강실 높이가 낮고 길이가 길수록, 처리가스속도가 작을수록 집진율이 높아진다":"침강실이 낮고 길수록, 가스가 느리게 지날수록 입자가 가라앉을 시간이 늘어납니다.","침강실 높이가 높고 중력장 길이가 짧을수록 집진율이 높아지는 것은 아니다":"침강실이 높고 짧다고 집진율이 올라가는 것은 아닙니다.","카네카론·비닐론·글라스화이버는 내산성 여과재로 적합하다":"카네카론, 비닐론, 글라스화이버는 내산성 여과재로 알맞습니다.","캐노피형은 외부식 후드가 아니며, 전혀 포위 못해도 부스식을 쓰는 것은 아니다":"캐노피형은 외부식 후드가 아니며, 전혀 에워싸지 못한다고 해서 부스식을 쓰는 것도 아닙니다.","커질수록 항력계수가 증가하는 것이 아니라 스토크스영역에서는 24/Re로 감소한다":"레이놀즈수가 커지면 항력계수가 늘지 않고, 스토크스영역에서는 24/Re로 줄어듭니다.","코리올리 힘은 적도에서 최대가 아니라 0이며, 기압차로 풍속에 영향을 주지 않는다":"적도에서는 최대가 아니라 0이며, 기압 차이로 풍속이 변하는 것도 아닙니다.","코크스·석탄 불완전연소로 얻으며 주성분은 CO와 N2다":"발생로가스는 코크스나 석탄을 불완전연소시켜 얻으며 주성분은 CO와 N2예요.","크로모트로핀산법(H2SO4 발색) 또는 아세틸아세톤 흡수액법으로 분석한다":"포름알데히드는 크로모트로핀산법(H2SO4 발색)이나 아세틸아세톤 흡수액법으로 분석해요.","크롬 만성중독은 코·폐·위장 점막 병변, 비소는 피부염·각화증을 일으킨다":"크롬은 코와 폐, 위장 점막에 병을 만들고, 비소는 피부염과 각화증을 만듭니다.","탄소결합 절단보다 탈수소가 쉬운 연료, C/H비가 큰 연료일수록 매연이 많다":"탄소결합을 끊기보다 수소를 떼기 쉬운 연료, 그리고 C/H비가 큰 연료에서 매연이 늘어납니다.","탄소수가 많거나 불포화도가 높을수록 단위부피당 이론공기량이 크다":"탄소 수가 많고 불포화도가 높은 연료는 연소에 공기가 더 많이 들어갑니다.","탄소수가 증가할수록 옥탄가가 저하해 C7에서 0이 된다":"n-파라핀은 탄소가 늘수록 노킹을 일으키기 쉬워 C7이면 옥탄가가 0이 됩니다.","탄화도가 높을수록 착화온도가 낮아지거나 비열이 높아지지는 않는다":"탄화가 진행되어도 착화온도가 내려가거나 비열이 올라가지는 않습니다.","탈수소·중합·고리화합물 생성 등 축합반응이 쉬운 탄화수소일수록 매연이 잘 생긴다":"탈수소, 중합, 고리화합물 생성처럼 축합이 쉬운 탄화수소가 그을음을 많이 냅니다.","탈진시 재비산이 적어 집진율이 높은 방식이 아니다":"연속식은 털 때 먼지가 다시 날리는 일이 적어서 집진율이 높다고 하면 틀립니다.","테들라백·시료채취주머니는 재사용 원칙이 아니라 새 것 사용이 원칙이다":"주머니는 쓰던 것을 다시 쓰지 않고 새것을 쓰는 것이 원칙입니다.","톨루엔 0.05, TVOC 20.0·4.0 이하는 기준치가 아니다":"톨루엔 0.05와 TVOC 20.0, 4.0은 방출 기준으로 정해진 값이 아닙니다.","톨루엔 1000, 에틸벤젠 360㎍/m3 이하다":"신축공동주택 권고기준은 톨루엔 1000㎍/m3 이하, 에틸벤젠 360㎍/m3 이하입니다.","투과광 강도÷입사광 강도이다":"투과도는 투과광의 세기를 입사광의 세기로 나눈 값이에요.","투과도의 상용대수(로그)가 아니라 그 음수가 흡광도다":"흡광도는 투과도의 상용대수 자체가 아니라 그 음수입니다.","특별대책지역 등 환경기준 초과 우려 지역에서 실시한다":"총량규제는 특별대책지역처럼 환경기준을 넘을 우려가 있는 지역에서 실시해요.","티오시안산제이수은용액·황산제2철암모늄용액·메틸알코올":"티오시안산제이수은법의 시약은 티오시안산제이수은용액, 황산제2철암모늄용액, 메틸알코올입니다.","파쇄·선별·퇴적 등 기계적 처리나 연소·합성으로 발생하는 물질이다":"입자상물질은 파쇄, 선별, 퇴적 같은 기계적 처리나 연소, 합성 과정에서 생기는 물질이에요.","파장을 나타내는 직선이 아니라 스펙트럼 강도 분포를 나타내는 곡선이다":"선프로파일은 파장을 나타내는 직선이 아니라 스펙트럼의 강도 분포를 그린 곡선입니다.","펌프 내장으로 연속 시료공급되며 계기눈금은 ±5% 읽을 수 있어야 한다":"휴대용 VOCs 측정기기는 펌프가 내장돼 시료를 연속 공급하고 계기눈금을 ±5%까지 읽어야 해요.","페놀류를 NaOH용액에 흡수시켜 발색시킨다":"페놀류를 NaOH용액에 흡수시킨 뒤 발색시켜 분석하는 방법입니다.","페인트의 톨루엔 방출기준은 0.08 이하다":"페인트에서 톨루엔이 나오는 양은 0.08 이하여야 합니다.","포름알데히드는 적갈색이 아니라 무색 기체다":"포름알데히드 기체는 색이 없어 적갈색으로 보이지 않습니다.","포름알데히드의 주배출업종이 아니다":"금속정련공장은 포름알데히드가 주로 나오는 업종이 아닙니다.","포집입자 입경범위는 0.1~100㎛이며 공기흡인부·여과지홀더·유량측정부·보호상자로 구성된다":"포집 입경은 0.1~100㎛ 범위이고 흡인부, 여과지홀더, 유량측정부, 보호상자로 만듭니다.","포집·탈진이 동시에 일어나 압력손실이 일정하고 대용량에 적합하다":"연속식은 포집과 탈진이 동시에 일어나 압력손실이 일정하고 대용량 처리에 알맞습니다.","포함시 측정주기를 한 단계 강화해 적용한다":"특정유해물질이 포함되면 측정주기를 한 단계 강화하여 적용합니다.","폭굉온도가 연소온도보다 3~5배 높고 압력이 15~20배인 것은 아니다":"폭굉온도가 연소온도의 3~5배, 압력이 15~20배라는 설명은 맞지 않습니다.","폭발하한농도가 높을수록 위험도가 증가하는 것이 아니라 낮을수록 위험도가 커진다":"폭발하한이 낮을수록 위험도가 크며, 하한이 높아서 위험도가 커지는 것은 아닙니다.","표준온도는 0℃, 상온은 15~25℃, 실온은 1~35℃, 냉수는 15℃ 이하다":"공정시험기준 총칙에서 표준온도 0℃, 상온 15~25℃, 실온 1~35℃, 냉수 15℃ 이하로 구분합니다.","표준품은 원칙적으로 특급시약을 쓰고, ppm은 기체는 용량대 용량이다":"표준품은 원칙적으로 특급시약을 쓰고, 기체의 ppm은 부피 대 부피 비로 나타냅니다.","표지 바탕색은 노란색, 문자는 검정색이다":"운행정지표지의 바탕색은 노란색이고 문자는 검정색입니다.","풍량(Q)은 회전수(N)에 비례한다(Q1/N1=Q2/N2)":"풍량 Q는 회전수 N에 비례하여, Q1/N1과 Q2/N2가 같습니다.","풍량·송풍기 크기가 회전수 제곱에 비례하는 것은 아니다":"풍량과 송풍기 크기가 회전수 제곱에 맞춰 커진다는 설명은 틀립니다.","풍속 0.2m/s 이하는 정온(Calm) 상태로 본다":"바람이 0.2m/s 이하로 약하면 정온(Calm) 상태라고 부릅니다.","풍속은 막대 날개 길이가 아니라 다른 방식으로 표시한다":"바람장미에서 풍속은 막대 날개의 길이가 아니라 다른 방식으로 나타냅니다.","풍속이 높이에 반비례하거나 거듭제곱법칙을 따른다고 가정하지 않는다":"풍속이 높이에 반비례한다거나 거듭제곱 식을 따른다는 가정은 이 모델에 없습니다.","프로피온산 기준은 0.1ppm·0.07ppm이 아니며, I-발레르산도 0.05ppm이 아니다":"프로피온산과 I-발레르산의 배출기준은 이 문장에 쓴 수치들과 다릅니다.","프로필렌옥사이드·아닐린·이황화메틸·불소화물·니켈화합물":"특정대기유해물질에는 프로필렌옥사이드, 아닐린, 이황화메틸, 불소화물, 니켈화합물이 있습니다.","플라스틱·PVC소각·소다공업":"염화수소는 플라스틱과 PVC 소각, 소다공업에서 주로 배출됩니다.","피토관 바깥지름은 4~10mm, 분기관-오리피스 거리는 바깥지름의 1.05~1.50배다":"관 지름은 4~10mm 범위이며, 분기관과 오리피스 사이는 지름의 1.05~1.50배를 둡니다.","피토관·열선유속계·와류유속계가 있다":"배출가스 유량은 피토관, 열선유속계, 와류유속계로 측정합니다.","한 채취점 채취시간은 최소 30초 이상이 아니라 다른 기준을 적용한다":"채취점 하나에서 얼마나 오래 뽑는지는 30초 이상이 아닌 별도 기준이 있습니다.","할로겐화합물은 부(-)오차, 무기질산염·아질산염은 정(+)오차를 일으킨다":"할로겐화합물은 측정값을 낮추는 부(-)오차를, 무기질산염과 아질산염은 높이는 정(+)오차를 일으킵니다.","합성수지·포르말린·피혁공장에서 주로 발생한다":"포름알데히드는 합성수지, 포르말린, 피혁공장에서 주로 배출되는 물질이에요.","항력계수가 커질수록, 투영면적이 클수록 항력이 증가한다":"항력은 항력계수가 클수록, 투영면적이 클수록 증가합니다.","항력은 상대속도의 제곱에 비례해 증가한다":"항력은 상대속도를 제곱한 만큼 커집니다.","해양의 DMS가 황화합물 자연배출원 중 가장 많으며 SO2는 물에 잘 녹아 반응성이 크다":"바다의 DMS가 자연 배출 황화합물 중 가장 많고, SO2는 물에 잘 녹아 반응성이 큽니다.","해양투기 방지가 아니라 유해폐기물의 국가간 이동 규제 협약이다":"바젤협약이 규제하는 것은 바다에 버리는 일이 아니라 유해폐기물의 국경 간 이동입니다.","해풍은 보통 그 밤의 육풍보다 강하며, 휀풍은 풍상측 경사면에서 건조단열 상승한다":"해풍은 대체로 밤의 육풍보다 세고, 휀풍은 바람을 맞는 경사면에서 단열 상승합니다.","허가받은 용도에 다른 용도를 추가하는 것은 변경신고가 아니라 변경허가 대상이다":"허가받은 용도에 다른 용도를 더하는 일은 변경신고가 아니라 변경허가를 받아야 합니다.","헨리상수 단위는 atm·m3/kmol이며 atm/m3·kmol이 아니다":"헨리상수는 압력에 부피를 곱해 몰수로 나눈 꼴의 단위로 적습니다.","헨리정수는 온도가 높을수록 커지며, 흡수액 점성은 커야 하는 것이 아니다":"온도가 오르면 헨리정수가 커지고, 흡수액은 끈적일수록 좋다고 하면 틀립니다.","헴(heme) 합성효소를 방해해 포르피린 고리 형성을 저해, 빈혈을 유발한다":"납은 헴(heme) 합성효소를 방해해 포르피린 고리 형성을 막아 빈혈을 일으킵니다.","혼합기체 분출속도가 불꽃 연소속도보다 작을 때 연소가 내부로 옮겨지는 현상이다":"역화는 혼합기체 분출속도가 불꽃의 연소속도보다 느릴 때 불이 버너 안쪽으로 옮겨가는 현상입니다.","혼합비가 균일해 화염온도가 높고 화염길이가 짧다":"예혼합연소는 연료와 공기가 고르게 섞여 있어 화염온도가 높고 불꽃이 짧아요.","화염분할·완만연소로 열손실을 늘려 화염온도 상승을 억제한다":"화염분할과 완만연소는 열손실을 늘려 화염온도가 올라가는 것을 억제합니다.","화염이 길고 그을음이 나며 역화 위험이 없다":"확산연소는 불꽃이 길고 그을음이 생기지만, 불이 버너 안으로 되돌아오는 역화 위험은 없어요.","화학결합 활성도가 작을수록 착화온도는 낮아지는 것이 아니라 높아진다":"결합 활성도가 낮은 연료는 쉽게 반응하지 않아 불이 붙는 온도가 오히려 올라갑니다.","화학발광법·적외선흡수법으로 측정한다":"질소산화물은 화학발광법과 적외선흡수법으로 연속 측정해요.","화학비료·무기안료 제조시설의 암모니아 기준은 20ppm 이하다":"화학비료와 무기안료를 만드는 시설은 암모니아를 20ppm 이하로 내보내야 합니다.","화학약품 제조업 제조시설이나 VOC 분석 실험실은 신고대상이 아니다":"화학약품 제조 시설과 VOC 분석 실험실은 신고해야 하는 시설이 아닙니다.","화학적 성질이 아니라 물리적 성질로 발생하는 기체상물질로 정의된다":"화학반응이 아니라 물리적 성질로 생긴 기체상 물질을 법에서는 가스라고 정의합니다.","확산조건·오염원 주변기류는 제어속도에 영향을 크게 준다":"후드 주변 기류와 확산 상태가 제어속도를 얼마로 잡을지에 크게 작용합니다.","환경감률이 건조단열감률과 같은 기층에서는 온위가 일정(중립)하다":"기온이 높이에 따라 건조단열감률로 변하는 층에서는 온위가 변하지 않아 중립이 됩니다.","환경감률이 건조단열감률보다 클 때다":"과단열조건은 환경감률이 건조단열감률보다 클 때를 말합니다.","환경기술인을 바꾸어 임명한 경우 사유발생일로부터 5일 이내 신고한다":"환경기술인을 바꿔 임명하면 사유가 생긴 날부터 5일 이내에 신고합니다.","환경기술인 임명신고는 가동개시신고와 동시에 한다":"환경기술인 임명신고는 최초 설치 때 가동개시신고와 동시에 해요.","환경담당자 교육사항 변경은 변경신고 사유가 아니며, 과태료가 50만원·200만원도 아니다":"환경담당자 교육사항이 바뀐 것은 신고 사유가 아니며, 과태료도 50만원이나 200만원이 아닙니다.","환경대기 SO2 측정법에 포함된다":"용액전도율법은 환경대기의 SO2 측정법에 들어갑니다.","환경대기·지하공간 중 벤조(a)피렌은 형광분광광도법으로 측정한다":"형광분광광도법으로 환경대기와 지하공간의 벤조(a)피렌을 잽니다.","환경보전협회는 대기오염도 검사기관이 아니다":"환경보전협회는 대기오염도 검사기관에 속하지 않아요.","환경보전협회이며 교육기간은 4일 이내다":"교육은 환경보전협회에서 하며 교육기간은 4일 이내입니다.","환경부장관이 고시한 악취 유발 시설·기계·기구다":"악취배출시설은 환경부장관이 고시한 악취 유발 시설, 기계, 기구입니다.","환경부장관이 설치하는 측정망에 속한다":"지구대기측정망도 환경부장관이 설치하는 측정망에 속합니다.","환경부장관이 아니라 시·도지사 등이 설치한다":"대기중금속측정망은 환경부장관이 아니라 시·도지사 등이 설치해요.","환이 커지면 냄새가 강해지는 것이 아니라 약해진다":"락톤과 케톤은 환이 커지면 냄새가 강해지지 않고 약해집니다.","활성탄화수소·비메탄탄화수소·총탄화수소 측정법이 있다":"탄화수소 측정법에는 활성탄화수소, 비메탄탄화수소, 총탄화수소 측정법이 있어요.","황분·독성이 적고 프로판·부탄이 주성분이며 공기보다 무겁다":"LPG는 유황과 독성이 적고, 프로판과 부탄이 주성분이어서 공기보다 무겁습니다.","황산+과산화수소수 흡수제로 질산이온을 만들어 페놀디술폰산으로 발색시킨다":"황산과 과산화수소수로 질산이온을 만든 다음, 페놀디술폰산을 넣어 색이 나게 합니다.","황산화물·매연·아연화합물 등":"자가측정 대상 오염물질에는 황산화물, 매연, 아연화합물 등이 있습니다.","황산화물이 황산으로 변하면 부식성이 더 약해지는 것이 아니라 강해진다":"황산화물이 황산으로 바뀌면 물체를 갉아먹는 힘이 더 세집니다.","황·질소가 있으면 냄새가 강하며 에스테르는 원료보다 방향이 우세하다":"황이나 질소 원자가 들어 있으면 냄새가 세지고, 에스테르는 향이 원료보다 짙습니다.","황함량분석기(1ppm 이하 분석 가능)를 갖춰야 하며 LPG·CNG 검사기관 기술능력기준은 같다":"황함량분석기는 1ppm 이하도 분석할 수 있어야 하고, LPG·CNG 검사기관도 같은 기술능력 기준입니다.","황함유량 구간별 농도별 부과계수(예 0.2)가 적용된다":"황이 얼마나 들었는지 구간별로 나눈 계수를 부과금 계산에 곱해 줍니다.","황화수소 5~1000ppm 범위 분석에 적합하다":"메틸렌블루법은 황화수소 5~1000ppm 범위를 분석하는 데 알맞아요.","황화수소·다이메틸다이설파이드·아세트알데하이드·메틸메르캅탄·톨루엔":"지정악취물질에는 황화수소, 다이메틸다이설파이드, 아세트알데하이드, 메틸메르캅탄, 톨루엔이 있어요.","황화수소·메르캅탄류·아민류 등 자극성 기체물질이 후각을 자극하는 것이다":"황화수소, 메르캅탄류, 아민류 같은 자극성 기체가 코를 자극하는 것을 악취라 합니다.","황화수소·질소산화물은 알칼리 충전탑으로, 벤젠은 촉매연소·활성탄흡착으로 처리한다":"황화수소와 질소산화물은 알칼리로 씻고, 벤젠은 태우거나 활성탄에 붙여 처리합니다.","황화합물은 산화상태가 클수록 증기압·용해성이 감소하는 것이 아니다":"황화합물은 산화가 많이 진행될수록 증기압과 용해성이 줄어든다고 하면 틀립니다.","회분이 거의 없고 점화·소화·연소조절이 쉬우며 발열량이 높고 성분이 일정하다":"재가 거의 없고 불 붙이고 끄기와 조절이 쉬우며, 열량이 높고 성분이 일정합니다.","휘발분 많은 물질을 공기를 아래에서 위로 보내 태우는 방식은 적합하지 않다":"휘발분이 많은 쓰레기는 아래에서 올려 불어 태우는 방식과 잘 맞지 않습니다.","휘발유·가스 겸용차는 휘발유차 기준을 그대로 적용하지 않는다":"휘발유와 가스를 함께 쓰는 차량에 휘발유차 기준을 통째로 적용하지는 않습니다.","휘발유·알코올·가스 사용차는 CO·NOx·탄화수소를 측정하며 황산화물은 제외다":"CO와 NOx, 탄화수소를 재며 황산화물은 부하검사 측정 항목에서 뺍니다.","휘발유 황함량 기준은 50ppm 이하가 아니다":"휘발유 황함량 상한을 50ppm으로 보는 것은 틀린 설명입니다.","휴대용 기기 응답시간은 60초 이하가 아니라 다른 기준이 적용된다":"응답시간은 60초 이하가 아닌 다른 기준을 따릅니다.","흡광광도법(질산토륨-네오트린법)과 란탄-알리자린 콜플렉손법":"불소화합물 분석법에는 질산토륨-네오트린법과 란탄-알리자린 콜플렉손법이 있어요.","흡광광도법(티오시안산제2수은법)으로 분석한다":"브롬화합물은 티오시안산제2수은법으로 색의 진하기를 재어 분석합니다.","흡광광도법·이온크로마토그래프법·이온전극법이 있다":"염화수소는 흡광광도법, 이온크로마토그래프법, 이온전극법으로 측정해요.","흡광도 눈금보정은 중크롬산칼륨용액으로 하며, 유리셀을 자외부에 쓰지 않는다":"흡광도 눈금은 중크롬산칼륨용액으로 맞추고, 자외선 영역에는 유리셀을 쓰지 않습니다.","흡수발색액으로 포집해 가온 발색시킨다":"포집한 시료를 흡수발색액에 넣고 따뜻하게 해서 색을 내는 방법입니다.","흡수액은 반응해 하이드라존을 만들며 HPLC로도 분석한다":"알데히드가 이 흡수액과 반응해 하이드라존이 되고, 액체크로마토그래프로 분석합니다.","흡수액인 산성 과망간산칼륨 용액에 채취해 Hg2+를 Hg0로 환원시켜 측정한다":"산성 과망간산칼륨 흡수액에 채취해 Hg2+를 Hg0로 환원시켜 측정하는 방법이에요.","흡인노즐 내경은 4mm 이상, 흡인관 온도는 120±14℃로 유지한다":"흡인노즐 안지름은 4mm 이상이어야 하며, 흡인관은 120±14℃로 데워 둡니다.","흡인노즐 내경이 2mm 이상이거나 꼭지점이 60°·80° 이하인 것은 아니다":"안지름이 2mm 이상이거나 꼭지점이 60°나 80° 이하라는 말은 틀립니다.","흡인펌프를 연속 10일 이상 사용하거나 진공도가 낮은 것을 쓰는 것은 아니다":"흡인펌프를 열흘 넘게 쉬지 않고 돌리거나 진공도가 낮은 것을 쓰지는 않습니다.","흡착제가 가장 많은 흡착질을 흡착하며 돌파곡선은 S자형이다":"파괴점은 흡착제가 흡착질을 가장 많이 흡착한 지점이고, 돌파곡선은 S자 모양이에요.","흡착·촉매반응·오존산화·응축·미생물처리 시설":"흡착, 촉매반응, 오존산화, 응축, 미생물처리 시설이 대기오염 방지시설에 해당해요.","희박연소 방식 자동차는 공기과잉률 기준을 적용하지 않는다":"희박연소 자동차는 공기과잉률 기준이 적용되지 않는 차종입니다.","희석법은 대량 공기로 희석하는 저렴한 방법이고, 흡착은 주로 물리흡착을 쓴다":"희석법은 대량의 공기로 묽히는 값싼 방법이며, 흡착은 주로 물리흡착을 이용합니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
